(function (all) { var mine = all["hi"] = all["hi"] || {}; var add = {"manual.831d0f72d242":"शुरुआत करें","manual.f2f53974b760":"Freally Capture, Windows, macOS और Linux के लिए एक डेस्कटॉप स्टूडियो है। यह मैनुअल वर्तमान रिलीज़, संस्करण 1.2.1 का वर्णन करता है।","manual.4b5f10daa08b":"Freally Capture खोलें। पहली बार यह आपसे अपना लाइसेंस अनुबंध स्वीकार करने को कहता है; फिर एक सेटअप विज़ार्ड आपके ग्राफ़िक्स कार्ड और प्रोसेसर की जाँच करता है और एक एनकोडर, एक कैनवस आकार और एक बिटरेट सुझाता है — हर एक का कारण बताते हुए।","manual.fe88634050bf":"स्टूडियो प्रोग्राम प्रीव्यू के साथ खुलता है, जिसके साथ <strong>सीन</strong>, <strong>सोर्स</strong>, <strong>मिक्सर</strong> और <strong>नियंत्रण</strong> डॉक होते हैं। न कोई खाता है, न कोई साइन-इन।","manual.4c937d2528ca":"<strong>macOS</strong> पर, सिस्टम सेटिंग्स → गोपनीयता और सुरक्षा में <strong>स्क्रीन रिकॉर्डिंग</strong> की अनुमति दें — और अगर आप इनका इस्तेमाल करते हैं तो <strong>कैमरा</strong> और <strong>माइक्रोफ़ोन</strong> की भी — फिर ऐप दोबारा खोलें। <strong>Wayland वाले Linux</strong> पर, डेस्कटॉप का अपना डायलॉग पूछता है कि कौन-सी स्क्रीन या विंडो साझा करनी है।","manual.adc8f305f8f8":"अपना पहला सोर्स जोड़ें (<a href=\"#build-a-scene\">सीन बनाएँ</a> देखें) और आप रिकॉर्ड करने या लाइव जाने के लिए तैयार हैं।","manual.46e49bd74b1d":"सीन बनाएँ","manual.f779d891c1f2":"सीन सोर्स का एक स्टैक है, जिसे ग्राफ़िक्स कार्ड पर कंपोज़ किया जाता है। एक सोर्स कई सीन में साझा किया जा सकता है।","manual.5a1c5f778fdb":"<strong>सोर्स</strong> डॉक में <strong>स्रोत जोड़ें</strong> पर क्लिक करें और एक प्रकार चुनें: <strong>डिस्प्ले</strong>, <strong>विंडो</strong>, <strong>गेम</strong>, <strong>वेबकैम / कैप्चर कार्ड</strong>, <strong>ब्राउज़र</strong>, <strong>मीडिया</strong>, <strong>इमेज</strong>, <strong>टेक्स्ट</strong>, <strong>रंग</strong> या <strong>ऑडियो</strong>।","manual.2a2d9e2015b5":"एक <strong>डिस्प्ले कैप्चर</strong> जोड़ें: प्रोग्राम प्रीव्यू आपकी स्क्रीन से भर जाता है।","manual.80c8e9c8176f":"एक <strong>वेबकैम</strong> सोर्स जोड़ें, उसे कैनवस के किसी कोने में खींचें और उसके हैंडल से उसका आकार बदलें।","manual.264150f36676":"सबसे ऊपर एक <strong>इमेज</strong> या <strong>ब्राउज़र</strong> ओवरले जोड़ें। सूची का क्रम ही कैनवस पर क्रम है: सूची में सबसे ऊपर वाला सबसे आगे दिखता है।","manual.a329c46899d6":"<strong>सीन</strong> डॉक में और सीन बनाएँ — उदाहरण के लिए &quot;जल्द शुरू&quot;, &quot;गेमप्ले&quot; और &quot;थोड़ी देर में लौटते हैं&quot; — और उनके बीच स्विच करें।","manual.9c8d5730d1bb":"<strong>सुझाव:</strong> किसी साझा सोर्स की प्रॉपर्टीज़ एक बार बदलें, और वे उसे इस्तेमाल करने वाले हर सीन में बदल जाती हैं।","manual.fd869e76d280":"<strong>प्रीव्यू:</strong> Windows, macOS और X11 वाले Linux पर प्रोग्राम प्रीव्यू सीधे ग्राफ़िक्स कार्ड से बनाया जाता है, इसलिए खींचना, स्केल करना और घुमाना तुरंत होता है। Wayland पर एक सामान्य प्रीव्यू इस्तेमाल होता है, जिसमें कैनवस पर वही एडिटिंग होती है।","manual.87eca68fecaa":"फ़िल्टर और ट्रांज़िशन","manual.36a962cf3902":"हर सोर्स पर ग्राफ़िक्स कार्ड पर चलने वाले फ़िल्टर एक के ऊपर एक लगाएँ, और चुनें कि एक सीन अगले सीन को किस तरह जगह देता है।","manual.4708b4dbab34":"क्रोमा की जोड़ें","manual.9df34cebcaf5":"किसी सोर्स पर राइट-क्लिक करें — मान लीजिए ग्रीन-स्क्रीन वाला कैमरा — और <strong>फ़िल्टर</strong> चुनें।","manual.9981601a6174":"<strong>क्रोमा की</strong> जोड़ें और <strong>की रंग</strong>, <strong>समानता</strong>, <strong>चिकनाई</strong> और <strong>स्पिल</strong> समायोजित करें: की किया गया रंग कैनवस पर लाइव ग़ायब हो जाता है।","manual.b76bd309a9f6":"ज़रूरत के अनुसार और फ़िल्टर जोड़ें — <strong>कलर करेक्शन</strong>, <strong>LUT</strong>, <strong>ब्लर</strong>, <strong>मास्क</strong>, <strong>शार्पन</strong> — और चेन का क्रम बदलने के लिए उन्हें खींचें।","manual.db41fe5a40e4":"ट्रांज़िशन सेट करें","manual.bea9e11be98d":"<strong>नियंत्रण</strong> में ट्रांज़िशन पिकर खोलें, <strong>कट</strong>, <strong>फ़ेड</strong>, <strong>स्लाइड</strong>, <strong>स्वाइप</strong>, <strong>स्टिंगर</strong> या <strong>ल्यूमा वाइप</strong> चुनें, और एक अवधि सेट करें।","manual.eada58ce5b2e":"<strong>स्टिंगर</strong> के लिए मीडिया और उसका ट्रांज़िशन पॉइंट चुनें; <strong>ल्यूमा वाइप</strong> के लिए ग्रेडिएंट और उसकी कोमलता चुनें।","manual.79756cb8b209":"ट्रांज़िशन चलते देखने के लिए सीन बदलें। स्टूडियो मोड में यह तब चलता है जब आप प्रीव्यू को प्रोग्राम में भेजते हैं।","manual.2c0c025b4264":"कंपोज़िटर और विज़ुअल इफ़ेक्ट","manual.b768e85eff32":"3D झुकाव, डाउनस्ट्रीम कीयर, फ़्रीज़ और क्लोन, कई तरह के ब्लर, नियमों वाले मोशन ट्रांज़िशन, एक शेडर स्टूडियो, बेज़ियर मास्क और ट्रैक-मैट स्टिंगर।","manual.d2b720eca5a5":"3D झुकाव और परिप्रेक्ष्य","manual.d665cc2f2296":"किसी आइटम पर <strong>ट्रांसफ़ॉर्म संपादित करें</strong> खोलें और सोर्स को 3D में पिन करने के लिए <strong>झुकाव X</strong>, <strong>झुकाव Y</strong> और <strong>परिप्रेक्ष्य</strong> की तीव्रता सेट करें। बिना झुकाव वाला ट्रांसफ़ॉर्म ठीक पहले जैसा ही रेंडर होता है।","manual.c4077ba2b72d":"डाउनस्ट्रीम कीयर","manual.d4220af54ed9":"<strong>उपकरण → डाउनस्ट्रीम कीयर</strong> खोलें और किसी भी सोर्स को <strong>प्रोग्राम आउटपुट</strong> के ऊपर एक लेयर के रूप में जोड़ें — हर सीन के ऊपर, और हर सीन बदलने के दौरान भी बनी रहने वाली — जैसे स्टेशन लोगो, LIVE बैज या लोअर थर्ड।","manual.0677e571c1f8":"लेयरों का क्रम बदलें और हर एक की अपारदर्शिता, स्थिति, आकार और चालू या बंद होना सेट करें। वे प्रीव्यू, रिकॉर्डिंग, स्ट्रीम और मल्टीव्यू में एक जैसी दिखती हैं।","manual.1e484119e149":"फ़्रीज़-फ़्रेम और सोर्स क्लोनिंग","manual.4cdb8e22f58b":"किसी सोर्स पर राइट-क्लिक करें, <strong>फ़िल्टर</strong> खोलें और <strong>फ़्रीज़</strong> जोड़ें: यह प्रोग्राम, प्रीव्यू, रिकॉर्डिंग और स्ट्रीम में एक साथ आख़िरी फ़्रेम रोककर रखता है। फ़्रीज़ हटाने के लिए इसे बंद करें।","manual.59fd957b48dc":"एक ही फ़ीड को कई सीन या जगहों पर रखने के लिए किसी सोर्स की पंक्ति पर <strong>क्लोन</strong> बटन (⧉) क्लिक करें; हर क्लोन का अपना ट्रांसफ़ॉर्म और अपने फ़िल्टर होते हैं।","manual.a90410d6b30c":"ब्लर","manual.eeb69e428aa3":"किसी सोर्स के <strong>फ़िल्टर</strong> में, गॉसियन के अलावा कोई एक ब्लर जोड़ें: <strong>दिशात्मक</strong> (किसी कोण पर गति की लकीर), <strong>रेडियल</strong> (किसी केंद्र के चारों ओर घुमाव), <strong>ज़ूम</strong> (डॉली-ज़ूम जैसी लकीर) या <strong>पिक्सेलेट</strong> (मोज़ेक)।","manual.54261c9f6b8f":"मूव ट्रांज़िशन और ट्रांज़िशन नियम","manual.ef17a04962be":"<strong>मूव</strong> ट्रांज़िशन चुनें: दोनों सीन में मौजूद आइटम कट होने के बजाय अपनी पुरानी स्थिति, स्केल, रोटेशन और क्रॉप से नए वालों तक सरकते हैं, और सिर्फ़ एक सीन में मौजूद आइटम फ़ेड इन या फ़ेड आउट होते हैं।","manual.e31792f9e737":"सीन की किसी एक जोड़ी को उसका अपना ट्रांज़िशन और अवधि देने के लिए <strong>उपकरण → ट्रांज़िशन नियम</strong> खोलें। किसी आइटम की अपनी एंट्री के लिए, <strong>ट्रांसफ़ॉर्म संपादित करें</strong> में एक <strong>रिवील</strong> फ़ेड-इन सेट करें।","manual.bb4e30a1ea68":"WGSL शेडर स्टूडियो","manual.e475acf03bea":"फ़िल्टर के रूप में एक <strong>यूज़र WGSL इफ़ेक्ट</strong> जोड़ें और उसे लाइव संपादित करें। इसके स्लाइडर <code>// @param</code> एनोटेशन से बनते हैं, और बिल्ट-इन गैलरी में ग्रेस्केल, इनवर्ट, स्कैनलाइन और विनेट शामिल हैं।","manual.424ca3316822":"<strong>सुझाव:</strong> टाइप करते समय ही शेडर कंपाइल और जाँचा जाता है। अमान्य शेडर को अनदेखा कर दिया जाता है और सोर्स बिना फ़िल्टर के रेंडर होता है — क्रैश कभी नहीं होता।","manual.c24e8b5ee2c0":"बेज़ियर मास्क","manual.37870edaacbc":"<strong>फ़्रीहैंड मास्क</strong> फ़िल्टर जोड़ें और एक बंद पाथ बनाएँ: हैंडल खींचें, पॉइंट जोड़ने के लिए डबल-क्लिक करें, किसी पॉइंट को हटाने के लिए राइट-क्लिक करें। इसमें प्रीसेट आकार, हर किनारे के लिए फ़ेदर और इनवर्ट हैं।","manual.f44ad1306530":"किसी भी पाथ को ग्रेस्केल <strong>ल्यूमा-वाइप</strong> पैटर्न के रूप में निर्यात करें, ताकि उस आकार को ट्रांज़िशन के रूप में दोबारा इस्तेमाल किया जा सके।","manual.e4c8b0c52b3e":"ट्रैक-मैट स्टिंगर","manual.b35494db6ce6":"किसी स्टिंगर को अपनी पारदर्शिता <strong>ट्रैक मैट</strong> के रूप में ले जाने के लिए सेट करें, जिसमें फ़िल और मैट <strong>साथ-साथ</strong> या <strong>ऊपर-नीचे</strong> हों, ताकि पारदर्शिता उन कोडेक में भी बची रहे जो उसे हटा देते हैं (H.264 और HEVC)। चाहें तो स्टिंगर चलते समय उसकी अपनी आवाज़ के नीचे <strong>प्रोग्राम ऑडियो को डक करें</strong>।","manual.3879f0c73d18":"ओवरले और अन्य सोर्स","manual.cea21c089e39":"रीप्ले, प्लेलिस्ट, टाइटल, मीटर, आँकड़ा ओवरले, टाइमर, इनपुट ओवरले और दो नेटवर्क फ़ीड — सब <strong>सोर्स</strong> डॉक के <strong>+ / स्रोत जोड़ें</strong> मेन्यू से।","manual.4a459b922e4b":"इंस्टेंट रीप्ले","manual.2e042aa67065":"पहले रीप्ले बफ़र सक्रिय करें (<strong>नियंत्रण</strong> डॉक में <strong>रीप्ले सक्रिय करें</strong>), फिर <strong>+ / स्रोत जोड़ें</strong> से <strong>इंस्टेंट रीप्ले</strong> चुनें और उसे किसी सीन में रखें।","manual.d7645da473a6":"अपनी रीप्ले हॉटकी से पिछले कुछ सेकंड प्रोग्राम में चलाएँ — बिना री-एनकोड किए कॉपी किए गए, और <strong>100%</strong>, <strong>50%</strong> या <strong>25%</strong> गति पर चलाए गए; गढ़े हुए फ़्रेम जोड़ने के बजाय सिर्फ़ धीमे करके। चलते समय आगे-पीछे करें या रोकें।","manual.5b8095e70de0":"अंत में सोर्स अपने-आप ख़ाली हो जाता है, इसलिए शो अपने-आप लाइव पर लौट आता है।","manual.6433eaab9b10":"<strong>सुझाव:</strong> स्लो-मोशन रीप्ले जान-बूझकर बिना आवाज़ के है: धीमी की गई आवाज़ बिगड़ जाती, इसलिए उसे नकली बनाने के बजाय छोड़ दिया गया है।","manual.f0b63d46cd74":"मीडिया प्लेलिस्ट और पृष्ठभूमि संगीत","manual.37ed12f9d130":"<strong>मीडिया प्लेलिस्ट (बिना अंतराल)</strong> जोड़ें और एक क्रमबद्ध सूची बनाएँ, जिसमें हर आइटम के इन और आउट पॉइंट और क्यू पॉइंट हों। पूरी सूची एक ही डिकोडर से चलती है, इसलिए जोड़ फ़्रेम-सटीक और सचमुच बिना अंतराल के होते हैं।","manual.ef41fa6ad9b5":"चुनें कि यह कैसे चले — <strong>लूप</strong>, <strong>शफ़ल</strong> या <strong>आख़िरी पर रुकें</strong> — और अगले और पिछले की हॉटकी से इसमें आगे-पीछे जाएँ। सिर्फ़ ऑडियो वाली प्लेलिस्ट कैनवस पर <strong>मौजूदा ट्रैक का नाम</strong> दिखाती है और अपनी मिक्सर स्ट्रिप से चलती है; उसे सुनने के लिए उस स्ट्रिप का <strong>मॉनिटर</strong> बटन क्लिक करें।","manual.6e641ae2bd92":"ऐसे संगीत के लिए जो स्क्रीन पर कुछ दिखाए बिना चले, इसके बजाय <strong>+ / स्रोत जोड़ें → पृष्ठभूमि संगीत…</strong> चुनें और एक या ज़्यादा <code>.mp3</code>, <code>.wav</code> या <code>.flac</code> फ़ाइलें चुनें, चाहें तो शफ़ल करके। यह वीडियो बैकड्रॉप की अपनी आवाज़ म्यूट कर देता है, ताकि हमेशा एक ही चीज़ सुनाई दे।","manual.b9aad55133bf":"टाइटल और स्कोरबोर्ड डिज़ाइनर","manual.5382c093aaef":"डिज़ाइनर खोलने के लिए <strong>टाइटल / स्कोरबोर्ड</strong> जोड़ें: <strong>टेक्स्ट</strong>, <strong>इमेज</strong> और <strong>आकार</strong> लेयर एक के ऊपर एक रखें — आउटलाइन और छाया वाले टेक्स्ट, और अंदर आने व बाहर जाने के एनिमेशन (फ़ेड, स्लाइड, वाइप) के साथ।","manual.7b8fea70655a":"फ़ील्ड को किसी निगरानी में रखी फ़ाइल (CSV सेल या JSON पॉइंटर) या किसी स्टूडियो वेरिएबल से जोड़ें, फिर इसे लाइव नियंत्रित करें: सीन को छुए बिना नाम बदलें, स्कोर संपादित करें या एनिमेशन चलाएँ।","manual.88a9422e37a9":"ऑडियो विज़ुअलाइज़र","manual.87f4a5bdd624":"<strong>ऑडियो विज़ुअलाइज़र</strong> जोड़ें और एक स्टाइल चुनें — <strong>स्पेक्ट्रम बार</strong>, <strong>ऑसिलोस्कोप</strong> या स्टीरियो <strong>VU मीटर</strong> — फिर इसे किसी भी मिक्सर स्ट्रिप, ट्रैक या मास्टर मिक्स से जोड़ें। यह बैकड्रॉप वीडियो की आवाज़ भी दिखाता है।","manual.0ae90a461adb":"सोर्स की <strong>प्रॉपर्टीज़</strong> में हरे, पीले और लाल बैंड के लिए <strong>क्लासिक रंग</strong> चालू करें, या एक ही ठोस रंग के लिए इसे बंद रहने दें। आकार, बार की संख्या और गिरने की दर भी वहीं हैं।","manual.0d1ceffb08ba":"<strong>सुझाव:</strong> विज़ुअलाइज़र <strong>फ़ेडर के बाद</strong> सुनता है, इसलिए म्यूट किया हुआ सोर्स सपाट दिखता है: यह ठीक वही दिखाता है जो आप सुनते हैं।","manual.ec642e1cf0cc":"आँकड़ा ओवरले, स्प्लिट टाइमर और इनपुट ओवरले","manual.6b4fe6f81cb0":"आँकड़ा डॉक के मापे गए आँकड़े कैनवस पर दिखाने के लिए <strong>प्रदर्शन आँकड़े (HUD)</strong> जोड़ें — फ़्रेम प्रति सेकंड, CPU, मेमोरी, GPU कंपोज़ समय, छूटे फ़्रेम और लाइव बिटरेट — हर पंक्ति अलग से चालू या बंद। GPU उपयोग जान-बूझकर छोड़ा गया है, क्योंकि उसे मापा नहीं जाता।","manual.cbd8a4b88736":"<strong>स्पीडरन स्प्लिट टाइमर</strong> जोड़ें, एक LiveSplit <code>.lss</code> फ़ाइल आयात करें, और इसे ग्लोबल स्प्लिट, पूर्ववत, स्किप और रीसेट हॉटकी के साथ अपने पर्सनल बेस्ट, बेस्ट सेगमेंट या औसत के मुक़ाबले चलाएँ। फ़ाइल सिर्फ़ पढ़ी जाती है; कोई रन कभी वापस उसमें नहीं लिखा जाता।","manual.fbf4bbeaf903":"कीबोर्ड, माउस और गेमपैड को लाइव दिखाने के लिए <strong>इनपुट ओवरले (कुंजियाँ/पैड)</strong> जोड़ें, चार लेआउट में से किसी एक में (WASD, कॉम्पैक्ट कीबोर्ड, ट्विन-स्टिक पैड, 8-दिशा वाला फ़ाइट स्टिक)। कीबोर्ड और माउस Windows पर काम करते हैं; गेमपैड तीनों सिस्टम पर काम करते हैं।","manual.bf794edb3c25":"सोशल और चैनल बार","manual.5f898056ef11":"<strong>+ / स्रोत जोड़ें</strong> से <strong>सोशल बार</strong> जोड़ें: एक पैनल जो आपके हैंडल की सूची दिखाता है। हर पंक्ति के लिए एक प्लेटफ़ॉर्म चुनें — रंगीन बैज के रूप में <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong>, या अपने लेबल और रंग के साथ <strong>कस्टम</strong> — और हैंडल टाइप करें (उदाहरण के लिए <code>@mychannel</code>)। चाहें तो एक हेडर पंक्ति (&quot;मुझे फ़ॉलो करें&quot;) जोड़ें, पंक्तियों का क्रम बदलें, और टेक्स्ट का आकार और रंग सेट करें।","manual.1dab9389547a":"हर फ़ील्ड सोर्स की <strong>प्रॉपर्टीज़</strong> में संपादन-योग्य रहता है। बिना हैंडल वाली पंक्तियाँ छोड़ दी जाती हैं, इसलिए आप पूरी सूची रख सकते हैं और सिर्फ़ वही भर सकते हैं जो आप इस्तेमाल करते हैं।","manual.1a4ac3c2e0bf":"विशेष चैट संदेश","manual.c5d58a7d58be":"<strong>उपकरण → विशेष चैट संदेश…</strong> खोलें (या कमांड पैलेट)। यह हर चल रहे चैट ओवरले की सबसे नई पंक्तियों की सूची दिखाता है: किसी एक पर <strong>फ़ीचर</strong> क्लिक करें, ताकि वह प्रोग्राम पर एक बैनर के रूप में पिन हो जाए, जिसे स्ट्रीम और रिकॉर्डिंग के दर्शक देखते हैं।","manual.162d364796a2":"डायलॉग में <strong>बैनर</strong> और <strong>टेक्स्ट</strong> के रंग सेट करें, और उसे ऑफ़ एयर करने के लिए <strong>साफ़ करें</strong> क्लिक करें। पिन ख़ुद रीस्टार्ट पर हट जाता है, और ऐसा जान-बूझकर है: कल का शाउट-आउट आज के शो में कभी नहीं लौटता।","manual.89a84c53e014":"कर्सर हाइलाइट और क्लिक इफ़ेक्ट","manual.d0a5d9fb047d":"किसी डिस्प्ले या विंडो कैप्चर पर राइट-क्लिक करें, <strong>फ़िल्टर</strong> खोलें और <strong>कर्सर प्रभाव</strong> जोड़ें: एक <strong>कर्सर हेलो</strong> (रंग और त्रिज्या), बाएँ और दाएँ क्लिक के लिए अलग-अलग रंग वाली <strong>क्लिक तरंगें</strong>, और पॉइंटर के पास वैकल्पिक <strong>कुंजी संकेत</strong>। बदलाव लाइव दिखते हैं।","manual.4a17c44757e4":"<strong>नोट:</strong> कर्सर प्रभाव सिर्फ़ Windows पर काम करते हैं; macOS और Linux कर्सर ख़ुद बनाते हैं। इनपुट ओवरले और कुंजी संकेत इनपुट <strong>सिर्फ़ तभी पढ़ते हैं जब वे चालू हों</strong>, और उसे सीधे तस्वीर में बनाते हैं: कुछ भी सहेजा या लॉग नहीं किया जाता।","manual.8bdb1aadf964":"नेटवर्क सोर्स: LAN इनजेस्ट और Freally Link","manual.797fe86a1fe8":"इस कंप्यूटर पर एक लिसनर खोलने के लिए <strong>LAN इनजेस्ट (SRT/RTMP लिसनर)</strong> जोड़ें, फिर किसी फ़ोन कैमरा ऐप, एनकोडर या दूसरे कंप्यूटर को दिखाए गए पते (QR कोड के साथ) पर भेजें। यह अपनी मिक्सर स्ट्रिप के साथ सीन में आ जाता है। SRT में वैकल्पिक AES पासफ़्रेज़ हो सकता है; RTMP का अपना कोई प्रमाणीकरण नहीं है, इसलिए फ़ॉर्म SRT को प्राथमिकता देता है।","manual.e2761818ccef":"Freally Capture की दो कॉपियों के बीच साझा करने के लिए, <strong>भेजने वाले</strong> कंप्यूटर पर <strong>Freally Link</strong> आउटपुट चालू करें और उसकी <strong>पेयरिंग कुंजी</strong> सेट करें — इसके बिना इसे चालू नहीं किया जा सकता। <strong>पाने वाले</strong> कंप्यूटर पर <strong>Freally Link (दूसरा इंस्टेंस)</strong> जोड़ें, <strong>LAN स्कैन करें</strong> क्लिक करें और कुंजी टाइप करें: भेजने वाले का प्रोग्राम एक सोर्स के रूप में दिखता है। किसी भी तरफ़ ffmpeg की ज़रूरत नहीं, और कुंजी के बिना पाने वाले को एक भी फ़्रेम नहीं दिखता।","manual.a793cb271e32":"<strong>नोट:</strong> दोनों नेटवर्क सोर्स <strong>तब तक बंद रहते हैं जब तक आप उन्हें जोड़ें नहीं</strong>, आपके अपने नेटवर्क पर ही रहते हैं, और इंटरनेट को कभी नहीं छूते: न कोई आपको ढूँढता है, न कुछ बाहर कनेक्ट करता है।","manual.de10be5dcf2c":"&quot;जल्द शुरू&quot; काउंटडाउन","manual.71b47ef78ea4":"एक क्लिक में शो से पहले की होल्डिंग स्क्रीन: शो के समय तक का एक बड़ा काउंटडाउन, किसी इमेज, GIF, वीडियो, ग्रेडिएंट या संगीत के ऊपर, जो शून्य पर चमकता है और आपके शो पर कट करने का इंतज़ार करता है।","manual.303493002776":"काउंटडाउन जोड़ें","manual.f78f2994b5d5":"<strong>सोर्स</strong> डॉक में <strong>+ / स्रोत जोड़ें</strong> खोलें और <strong>जल्द शुरू…</strong> चुनें। यह सीन पर पूरे कैनवस का काउंटडाउन रखता है — एक बड़ी संख्या के ऊपर एक कैप्शन।","manual.c4bff5a4f06e":"<strong>कैप्शन</strong> टाइप करें (&quot;जल्द शुरू&quot;, &quot;थोड़ी देर में लौटते हैं&quot;), फिर <strong>घड़ी पिकर</strong> से समय सेट करें: एक <strong>घंटा</strong> (1–12), पाँच-पाँच मिनट के अंतराल पर एक <strong>मिनट</strong>, और <strong>AM</strong> या <strong>PM</strong>। सोर्स दिन के उस समय तक उलटी गिनती करता है।","manual.59b00df516f1":"शून्य पर काउंटडाउन <strong>चमकता है और 0:00:00 पर रुका रहता है</strong> — यह कभी अपने-आप सीन नहीं बदलता। तैयार होने पर अपने लाइव सीन पर कट करें। हर फ़ील्ड सोर्स की <strong>प्रॉपर्टीज़</strong> में संपादन-योग्य रहता है।","manual.1dfb2d817d39":"बैकड्रॉप चुनें","manual.edc2450aeecd":"भराव चुनें: दो रंगों वाला <strong>ग्रेडिएंट</strong> (डिफ़ॉल्ट), एक <strong>ठोस</strong> रंग, एक <strong>इमेज</strong> (<strong>ब्राउज़ करें…</strong> क्लिक करें), या नीचे वाले सोर्स को दिखने देने के लिए <strong>पारदर्शी</strong>।","manual.07a5fd9ac032":"कोई <strong>GIF</strong> या <strong>वीडियो</strong> फ़ाइल चुनें और वह संख्याओं के पीछे लूप में चलती है, <strong>फ़िट होने तक स्केल की गई और बीच में रखी गई</strong>, ताकि पूरी तस्वीर दिखे और कुछ भी क्रॉप न हो।","manual.1cda5be75376":"डायलॉग के <strong>ब्राउज़ करें…</strong> से <strong>पृष्ठभूमि संगीत</strong> जोड़ें (MP3, WAV, FLAC, M4A, AAC, OGG या Opus)। यह लूप में चलता है, आप इसे प्रीव्यू में सुनते हैं, और यह रिकॉर्डिंग और स्ट्रीम का हिस्सा होता है। वीडियो बैकड्रॉप की अपनी आवाज़ म्यूट रहती है, ताकि हमेशा एक ही चीज़ सुनाई दे।","manual.b39b6b7add20":"<strong>सुझाव:</strong> सादी स्क्रीन के पीछे संगीत के लिए, बैकड्रॉप को ग्रेडिएंट या पारदर्शी पर छोड़ दें और संगीत जोड़ें: साउंडट्रैक के साथ एक साफ़-सुथरा काउंटडाउन।","manual.84f506f4fca5":"ऑडियो मिक्सर","manual.480e299c8728":"हर ऑडियो सोर्स को मिक्स करें, उसे 6 तक ट्रैक पर भेजें, और अपने माइक्रोफ़ोन की आवाज़ साफ़ करें — सब लाइव।","manual.bcbc220b3e63":"हर ऑडियो सोर्स <strong>मिक्सर</strong> में एक स्ट्रिप है: उसका नाम, लेवल मीटर, फ़ेडर, म्यूट, मॉनिटर, फ़िल्टर और ट्रैक बिंदु (1–6)।","manual.03b920dc5376":"लेवल सेट करने के लिए फ़ेडर खींचें, <strong>म्यूट</strong> या <strong>मॉनिटर</strong> क्लिक करें, और सोर्स को 6 में से किसी भी ट्रैक पर भेजें।","manual.9a9991c7dc36":"किसी सोर्स के <strong>फ़िल्टर</strong> खोलें और <strong>डीनॉइज़</strong> (पारंपरिक सिग्नल प्रोसेसिंग, कोई AI नहीं), <strong>नॉइज़ गेट</strong>, <strong>कंप्रेसर</strong>, <strong>लिमिटर</strong>, <strong>EQ</strong> या <strong>गेन</strong> जोड़ें।","manual.1a58b91bc5aa":"<strong>पुश-टू-टॉक</strong> या <strong>पुश-टू-म्यूट</strong> हॉटकी सेट करें, और प्रोग्राम की लाउडनेस के लिए <strong>LUFS</strong> मीटर पर नज़र रखें।","manual.7158a36ed4d5":"<strong>macOS नोट:</strong> macOS अपने-आप ऐप्स को &quot;जो आप सुनते हैं&quot; वह नहीं देता। जहाँ उपलब्ध हो, ScreenCaptureKit ऑडियो (macOS 13 या बाद का) इस्तेमाल करें, या BlackHole जैसा कोई वर्चुअल डिवाइस इंस्टॉल करें और उसे अपने सिस्टम-ऑडियो सोर्स के रूप में चुनें। Freally Capture आपको रास्ता बताता है, और कोई एक सोर्स न खुल पाए तब भी रिकॉर्डिंग जारी रखता है।","manual.bfdd510698ef":"रिकॉर्ड करें","manual.e39b756fce99":"अपने ग्राफ़िक्स कार्ड के हार्डवेयर एनकोडर से प्रोग्राम को कई ट्रैक पर रिकॉर्ड करें, या Capture के अपने फ़ॉर्मेट में लॉसलेस रिकॉर्ड करें।","manual.ad438c2dbf4b":"<strong>सेटिंग्स → आउटपुट</strong> में एक एनकोडर चुनें। Freally Capture <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> या <strong>VideoToolbox</strong> ढूँढता है और सबसे अच्छा चुनता है; प्रोसेसर पर चलने वाला <strong>x264</strong> विकल्प के रूप में हमेशा मौजूद रहता है।","manual.3bc1870f8449":"एक कंटेनर चुनें — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> या <strong>WebM</strong> — या Capture का अपना लॉसलेस <strong>freally-video</strong> फ़ॉर्मेट (<code>.frec</code>), जिसके लिए कुछ और इंस्टॉल करने की ज़रूरत नहीं।","manual.e2a332927058":"सोर्स को ऑडियो ट्रैक (6 तक) पर भेजें, ताकि एडिटिंग के लिए माइक्रोफ़ोन, सिस्टम साउंड और आपके मेहमान अलग रहें। चाहें तो <strong>फ़ाइल विभाजन</strong> और <strong>स्ट्रीमिंग के दौरान अलग-अलग ट्रैक वाली लोकल कॉपी</strong> चालू करें।","manual.e0fa2f5a9430":"<strong>नियंत्रण</strong> में <strong>रिकॉर्डिंग शुरू करें</strong> क्लिक करें। हरा <strong>REC</strong> बिंदु समय और ट्रैक की संख्या दिखाता है। फ़ाइल पूरी करने के लिए <strong>रोकें</strong> क्लिक करें।","manual.b1eb969490f1":"<strong>कोडेक नोट:</strong> H.264 और AAC (और HEVC या AV1) वाला MP4 पेटेंट के दायरे में आने वाले कोडेक इस्तेमाल करता है, जो <strong>ffmpeg</strong> से मिलते हैं, और ffmpeg <em>साथ बंडल नहीं है</em>: Freally Capture पहली बार ज़रूरत पड़ने पर उसे डाउनलोड करता है और उसकी जाँच करता है। लॉसलेस <strong>freally-video</strong> फ़ॉर्मेट के लिए कुछ भी डाउनलोड करने की ज़रूरत नहीं।","manual.691bff5377a8":"गहरी रिकॉर्डिंग और रीप्ले","manual.3c2d08430816":"फ़ाइल से जुड़ी हर चीज़: हर सोर्स की अलग रिकॉर्डिंग, क्लिप ट्रिमर, असली पारदर्शिता, घटनाओं पर फ़ाइल विभाजन और मार्कर, रिकॉर्डिंग के बाद के काम, अखंडता जाँच और SMPTE टाइमकोड। यह सब तब तक बंद रहता है जब तक आप इसे चालू न करें, और इसमें से कुछ भी ऑनलाइन नहीं जाता।","manual.537ffa2b9063":"हर सोर्स की ISO रिकॉर्डिंग","manual.e57aa725fa41":"<strong>सेटिंग्स → आउटपुट</strong> खोलें और <strong>ISO रिकॉर्डिंग</strong> ढूँढें। जिस भी सोर्स की साफ़ रिकॉर्डिंग चाहिए, उसके लिए <strong>&quot;{name}&quot; को उसकी अपनी ISO फ़ाइल के रूप में रिकॉर्ड करें</strong> चालू करें: हर एक कंपोज़िटिंग से पहले, कैनवस के आकार और फ़्रेम रेट पर रिकॉर्ड होता है, ताकि एडिटिंग टाइमलाइन पर हर फ़ाइल प्रोग्राम के साथ ठीक मेल खाए। हर रिमोट मेहमान एक सोर्स है, इसलिए हर मेहमान की भी अपनी फ़ाइल बनती है।","manual.4bce8f25ec9c":"प्रोसेस किए गए रूप के लिए <strong>सोर्स के फ़िल्टर के साथ रिकॉर्ड करें</strong> को चुना रहने दें, या कच्चे सोर्स के लिए इसे हटा दें, और हर रिकॉर्डिंग का <strong>ISO फ़ॉर्मैट</strong> और <strong>ISO वीडियो एनकोडर</strong> चुनें। ऑडियो फ़िल्टर के बाद लेकिन फ़ेडर और म्यूट से पहले लिया जाता है, इसलिए मिक्सिंग का कोई फ़ैसला किसी ISO फ़ाइल को कभी ख़ामोश नहीं करता।","manual.7f29ae4e2c55":"<strong>सुझाव:</strong> मध्यम श्रेणी के ग्राफ़िक्स कार्ड पर दो ISO रिकॉर्डिंग आराम से चलती हैं; हर अतिरिक्त रिकॉर्डिंग एक और रेंडर और एनकोड की लागत जोड़ती है, और पैनल यह बताता है।","manual.b2aad668b8b9":"रीप्ले और क्लिप ट्रिमर","manual.c8af16e1cd4f":"रिकॉर्डिंग की सूची से किसी सहेजी गई रिकॉर्डिंग को <strong>ट्रिम</strong> विंडो में खोलें, <strong>एक फ़्रेम पीछे</strong> और <strong>एक फ़्रेम आगे</strong> से उसमें आगे-पीछे जाएँ, और देखते हुए <strong>इन-पॉइंट</strong> और <strong>आउट-पॉइंट</strong> से अपने पॉइंट सेट करें।","manual.1f80dfd03a36":"निर्यात करने से पहले बैज देखें। हरा <em>&quot;बिना री-एनकोड किए निर्यात&quot;</em> बताता है कि इन-पॉइंट किसी कीफ़्रेम पर है (लगभग तुरंत और लॉसलेस); पीला बैज चेतावनी देता है कि री-एनकोड होगा — लॉसलेस कट के लिए इन-पॉइंट को कीफ़्रेम पर लाने हेतु <strong>कीफ़्रेम</strong> दबाएँ। <strong>क्लिप निर्यात करें</strong> क्लिक करें, या वर्टिकल संस्करण निर्यात करने के लिए <strong>9:16</strong> क्लिक करें।","manual.8a92b0b480f4":"पारदर्शिता के साथ रिकॉर्डिंग","manual.79bfd450e6aa":"प्रोग्राम को पारदर्शी पृष्ठभूमि पर Capture के <code>.frec</code> फ़ॉर्मेट में रिकॉर्ड करने के लिए <strong>सेटिंग्स → आउटपुट</strong> में <strong>पारदर्शिता (अल्फ़ा) के साथ रिकॉर्ड करें</strong> चालू करें। रिकॉर्डिंग को उसका अपना पारदर्शी रेंडर मिलता है, इसलिए आपके प्रीव्यू और स्ट्रीम में सामान्य तस्वीर बनी रहती है। अपने एडिटर के लिए रिकॉर्डिंग की सूची से <strong>ProRes 4444</strong> या <strong>QuickTime Animation (QTRLE)</strong> <code>.mov</code> निर्यात करें; MP4 और MKV पारदर्शिता को समतल कर देते हैं।","manual.fade0a9d0454":"<strong>नोट:</strong> पारदर्शिता <code>.frec</code> हेडर में सिर्फ़ एक फ़्लैग है, इसलिए ये फ़ाइलें हर उस जगह चलती हैं जहाँ <code>.frec</code> चलता है, और पुरानी फ़ाइलें अपारदर्शी के रूप में खुलती हैं।","manual.33e5c9a96c5d":"फ़ाइल विभाजन और अपने-आप लगने वाले मार्कर","manual.5596d47693a3":"<code>.frec</code> की विभाजन सेटिंग्स में, नई फ़ाइल <strong>दृश्य बदलने पर</strong>, <strong>मार्कर पर</strong> या <strong>रनडाउन चरण पर</strong> शुरू करना चुनें। हर हिस्सा उस घटना के ठीक फ़्रेम से शुरू होता है, और कोई भी हिस्सा कम से कम एक सेकंड का होता है, इसलिए घटनाओं की झड़ी से छोटी-छोटी फ़ाइलों का ढेर नहीं लग सकता।","manual.7fc20a49c196":"सीन बदलने, सहेजे गए रीप्ले, दोबारा कनेक्ट होने, छूटे फ़्रेमों की झड़ी, अलार्म और नियमों की कार्रवाइयों को चैप्टर के रूप में चिह्नित करने के लिए <strong>स्टूडियो घटनाओं पर अपने-आप चैप्टर मार्कर लगाएँ</strong> चालू करें। ये MKV चैप्टर शीर्षकों में और रिकॉर्डिंग के बगल वाली <code>.chapters.txt</code> फ़ाइल में जाते हैं, उन मार्करों के साथ जो आप अपनी हॉटकी से लगाते हैं।","manual.519fceb746f3":"रिकॉर्डिंग के बाद: पाइपलाइन और अखंडता जाँच","manual.561bb55d7a18":"हर प्रोफ़ाइल के लिए चरणों के एक तय सेट से एक <strong>रिकॉर्डिंग-पश्चात पाइपलाइन</strong> बनाएँ — <strong>जाँचें</strong>, <strong>MP4 में रीमक्स करें</strong>, <strong>लाउडनेस सामान्य करें</strong>, <strong>नाम बदलें</strong>, <strong>फ़ोल्डर में ले जाएँ</strong>, <strong>फ़ोल्डर में कॉपी करें</strong>, <strong>फ़ाइल प्रबंधक में दिखाएँ</strong> और <strong>Lua स्क्रिप्ट्स को सूचित करें</strong>। यह लाइव कतार के साथ बैकग्राउंड में चलती है और पहली विफलता पर रुक जाती है। इसमें जान-बूझकर &quot;कोई भी कमांड चलाएँ&quot; जैसा कोई चरण नहीं है।","manual.2f93cddd1f21":"रिकॉर्डिंग के बाद या जब चाहें अखंडता जाँच चलाएँ, ताकि <strong>कंटेनर</strong>, <strong>वीडियो निरंतरता</strong>, <strong>ऑडियो निरंतरता</strong>, <strong>ऑडियो और वीडियो इंटरलीविंग</strong> और <strong>अवधि</strong> पर सीधा-सादा ठीक, चेतावनी या विफल परिणाम मिले। <code>.frec</code> फ़ाइलों की गहरी जाँच होती है; दूसरी फ़ाइलों की ffmpeg के ज़रिए संरचना और डिकोड जाँच होती है।","manual.0d291aee5546":"रोकने पर साझा करने लायक़ कॉपी निर्यात करें","manual.124d2a00ed27":"<strong>सेटिंग्स → आउटपुट</strong> में, कंटेनर <code>.frec</code> पर सेट होने पर, <strong>मास्टर के साथ एक साझा-योग्य MP4 भी सहेजें</strong> पर टिक करें। रिकॉर्डिंग पूरी होने पर, बैकग्राउंड में एक निर्यात लॉसलेस मास्टर के बगल में एक ऐसी <code>.mp4</code> लिखता है जिसे कोई भी चला सके।","manual.a37303723389":"यह कॉपी रिकॉर्डिंग-पश्चात कतार में दिखती है, इसका नाम ऐसा रखा जाता है कि यह कभी किसी चीज़ को ओवरराइट न करे, और यह मास्टर को कभी नहीं छूती। जब तक आप इसे चालू न करें, यह बंद रहती है।","manual.7ed8656eb1ff":"SMPTE LTC टाइमकोड","manual.3d97874c3064":"<strong>SMPTE टाइमकोड (LTC)</strong> खोलें, <strong>किसी ट्रैक पर LTC बनाएँ</strong> चालू करें, और बाहरी रिकॉर्डर और कैमरों को फ़ीड देने के लिए मिक्सर ट्रैक और फ़्रेम रेट चुनें। आँकड़ा ओवरले पर टाइमकोड की पंक्ति दिखाने और LTC चैप्टर मार्कर लगाने के लिए <strong>LTC यहाँ से पढ़ें</strong> को किसी ऑडियो इनपुट पर सेट करें। पारंपरिक ऑडियो टाइमकोड, पूरी तरह ऑफ़लाइन, 24, 25 और 30 fps पर एक फ़्रेम तक सटीक।","manual.a9f690169703":"लाइव जाएँ","manual.8f6df4580812":"अपने कंप्यूटर से सीधे RTMP या RTMPS पर किसी प्लेटफ़ॉर्म पर स्ट्रीम करें — कभी हमारे किसी सर्वर से होकर नहीं।","manual.dba22b61cdcc":"<strong>सेटिंग्स → स्ट्रीम</strong> खोलें और <strong>गंतव्य जोड़ें</strong> क्लिक करें। <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> या <strong>कस्टम RTMP</strong> चुनें।","manual.2192731aac47":"अपनी <strong>स्ट्रीम कुंजी</strong> पेस्ट करें — यह आपके कंप्यूटर पर रहती है और छिपी हुई दिखाई जाती है — और उस सेवा के लिए बिटरेट और एनकोडर सेट करें।","manual.040014e94f16":"<strong>नियंत्रण</strong> में <strong>लाइव जाएँ</strong> क्लिक करें। <strong>लाइव</strong> लाइट जल उठती है, और आँकड़ा डॉक आपका बिटरेट, छूटे फ़्रेम और स्ट्रीम की सेहत दिखाता है।","manual.0cd441959cb4":"अगर आपका कनेक्शन टूट जाए, तो Freally Capture <strong>अपने-आप फिर से जुड़ जाता है</strong>, और स्ट्रीम के साथ जो भी हो, आपकी लोकल रिकॉर्डिंग चलती रहती है। चाहें तो एक <strong>स्ट्रीम विलंब</strong> सेट करें।","manual.dc8ebcea4893":"रोकने के लिए <strong>स्ट्रीम समाप्त करें</strong> क्लिक करें।","manual.973adc03e43c":"प्रसारण सुरक्षा","manual.53fa9293a65e":"शो न खोना — पहले, दौरान और बाद में।","manual.de8792b14216":"पहले: लाइव से पहले की जाँच","manual.ed9a4b7bfaf5":"<strong>लाइव जाएँ</strong> क्लिक करने पर पहले एक चेकलिस्ट चलती है: स्ट्रीम गंतव्यों के पास कुंजियाँ हैं, इस्तेमाल लायक़ एनकोडर मिला है, हर सोर्स ठीक है और रिकॉर्डिंग के लिए पर्याप्त डिस्क जगह है — हर एक हरा या लाल, एक क्लिक वाले सुधार के साथ — और साथ में माइक्रोफ़ोन और डेस्कटॉप-ऑडियो के लेवल और रीप्ले बफ़र के बारे में याद-दिहानियाँ, जो सिर्फ़ स्क्रीन वाले शो को कभी नहीं रोकतीं। एक सेटिंग <strong>हर रोकने वाली जाँच हरी होने तक लाइव जाना रोके रख सकती है</strong>; वरना &quot;फिर भी लाइव जाएँ&quot; का विकल्प मौजूद है।","manual.9b63c5c64ba1":"दौरान: अलार्म, सेहत और फ़ेलओवर","manual.9c386b745073":"जब आप लाइव हों या रिकॉर्ड कर रहे हों, <strong>सुरक्षा अलार्म</strong> नज़र रखते हैं: ख़ामोश प्रोग्राम ऑडियो, लगातार क्लिपिंग, काली या जमी हुई तस्वीर, और कम डिस्क जगह का <em>पूर्वानुमान</em> (&quot;मौजूदा बिटरेट पर लगभग 22 मिनट बाक़ी&quot;)। ये एक बैनर के रूप में दिखते हैं जिसे आप हटा सकते हैं, और स्क्रीन रीडर इनकी घोषणा करते हैं — कभी ऐसा डायलॉग नहीं जो शो में रुकावट डाले।","manual.b7c8c66a5330":"<strong>सोर्स हेल्थ डैशबोर्ड</strong> (कमांड पैलेट → &quot;सोर्स हेल्थ…&quot;) हर सोर्स की स्थिति, फ़्रेम रेट, उसके आख़िरी फ़्रेम की उम्र, छूटे फ़्रेम और रीस्टार्ट की सूची दिखाता है, हर एक के लिए <strong>पुनरारंभ करें</strong> और <strong>प्रॉपर्टीज़</strong> के साथ।","manual.92bd60ef963b":"अगर स्ट्रीम या रिकॉर्डिंग के बीच हार्डवेयर एनकोडर विफल हो जाए — ड्राइवर रीसेट हो, या ग्राफ़िक्स कार्ड पर ज़्यादा दबाव हो — तो <strong>एनकोडर फ़ेलओवर</strong> किसी दूसरे हार्डवेयर एनकोडर या x264 पर बदल देता है। स्ट्रीम फिर से जुड़कर चलती रहती है, रिकॉर्डिंग एक नई फ़ाइल में जारी रहती है, और एक संदेश ठीक-ठीक बताता है कि क्या हुआ। नेटवर्क की समस्याओं से कभी बदलाव नहीं होता।","manual.50a02fe4fe7b":"<strong>पैनिक बटन</strong> (आपकी चुनी हुई एक ग्लोबल हॉटकी) प्रोग्राम को — और वर्टिकल कैनवस और किसी भी प्रोजेक्टर को — एक प्राइवेसी स्लेट पर कट कर देता है, हर कैप्चर रोक देता है और माइक्रोफ़ोन समेत सारा ऑडियो म्यूट कर देता है, जबकि स्ट्रीम और रिकॉर्डिंग जुड़ी रहती हैं। वापस आने के लिए सोच-समझकर दो चरणों में पुष्टि करनी होती है। स्लेट का रंग या इमेज <strong>सेटिंग्स → हॉटकी</strong> में हॉटकी के बगल में सेट करें।","manual.a73a2857361e":"बाद में: सुरक्षित रिकॉर्डिंग और व्यवस्थित तरीक़े से बंद होना","manual.bf07b060e7e7":"MP4 और MOV रिकॉर्डिंग <strong>फ़्रैगमेंट</strong> में लिखी जाती हैं, इसलिए क्रैश या बिजली जाने पर भी चलने लायक़ फ़ाइल बची रहती है (MKV और <code>.frec</code> पहले से ऐसे थे)। अगर कोई सत्र रिकॉर्डिंग के बीच में ख़त्म हो जाए, तो अगली बार खोलने पर एक क्लिक में <code>(repaired)</code> कॉपी में <strong>मरम्मत करें</strong> का विकल्प मिलता है; मूल फ़ाइल को कभी छुआ नहीं जाता।","manual.da5eeb31c1b8":"लाइव रहते हुए, रिकॉर्ड करते हुए या रीप्ले सक्रिय रहते हुए बंद करने पर पहले दिखाया जाता है कि क्या होगा, फिर ऐप <strong>क्रम से</strong> बंद होता है: स्ट्रीम समाप्त, रिकॉर्डिंग पूरी, रीप्ले बफ़र सहेजा गया, आपका काम सहेजा गया।","manual.26b3f2c32e05":"<strong>रिकॉर्डिंग फ़ाइल नाम</strong> एक टेम्पलेट (<strong>सेटिंग्स → आउटपुट</strong>) का पालन करते हैं, जो टोकन से बनता है — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — रिकॉर्डिंग, रीप्ले और स्टिल के लिए, और रीप्ले और स्टिल के अपने अलग फ़ोल्डर होते हैं।","manual.27c3f23547ac":"<strong>डायग्नोस्टिक्स निर्यात करें</strong> तकनीकी जानकारी का एक बंडल आपके कंप्यूटर पर एक फ़ाइल में सहेजता है, जो एक सख़्त अनुमति-सूची से बनता है, ताकि स्ट्रीम कुंजियाँ, पासवर्ड, फ़ाइल पाथ और नाम उसमें कभी न हों। आप पहले पढ़ सकते हैं कि उसमें क्या है; वह वहीं रहता है जहाँ आप उसे सहेजते हैं और कभी कहीं नहीं भेजा जाता।","manual.5199babf9b90":"सोर्स और डिवाइस","manual.306121fdda68":"लेंस और कैनवस के बीच की हर चीज़: टेस्ट सिग्नल, सिंक कैलिब्रेशन, फ़ाइल से टेक्स्ट, टाइमर, हॉटकी मैप, गहरा मिक्सर और असली डिवाइस नियंत्रण।","manual.5eacf1ee941f":"टेस्ट सिग्नल और A/V सिंक कैलिब्रेशन","manual.920b7abd63cc":"एक <strong>टेस्ट सिग्नल</strong> सोर्स जोड़ें (<strong>सोर्स → + → टेस्ट सिग्नल</strong>): कलर बार, कैलिब्रेशन ग्रिड, मोशन स्वीप, −20 dBFS पर 1 kHz लाइनअप टोन, या ऑडियो-वीडियो सिंक के लिए मिला-जुला <strong>फ़्लैश और बीप</strong> — तस्वीर और आवाज़ एक ही घड़ी से बनी हुई। बिना कोई कैमरा लगाए किसी प्रोजेक्टर, एनकोडर या स्ट्रीम गंतव्य की जाँच करें।","manual.788073298328":"<strong>A/V सिंक कैलिब्रेशन</strong> वर्कबेंच खोलें (कमांड पैलेट → &quot;A/V सिंक कैलिब्रेशन…&quot;)। मिलाने के लिए कैमरा और माइक्रोफ़ोन चुनें, कैमरे को चमकते प्रोग्राम की ओर करें (डायलॉग इसके लिए एक फ़ुलस्क्रीन प्रोजेक्टर खोल सकता है), और इसे लगभग बारह सेकंड तक मापने दें। यह कई चक्रों में फ़्लैश और बीप ढूँढता है और मापा गया ऑफ़सेट माइक्रोफ़ोन पर लागू करने का विकल्प देता है; मैनुअल स्लाइडर विकल्प के रूप में बना रहता है। माप आपकी स्क्रीन और स्पीकर से होकर होता है, इसलिए उनकी अपनी छोटी देरी भी उसमें शामिल होती है — और विफल होने पर यह बताता है कि <em>क्यों</em>।","manual.825c83c405fb":"टाइमर, घड़ियाँ और फ़ाइल से टेक्स्ट","manual.85622b429b51":"एक <strong>टाइमर</strong> सोर्स घड़ी (आपके अपने फ़ॉर्मेट और वैकल्पिक तय UTC ऑफ़सेट के साथ), <strong>काउंटडाउन</strong> (किसी अवधि के लिए, या दिन के अगले किसी समय तक — शून्य पर यह चमक सकता है या सीन बदल सकता है), <strong>स्टॉपवॉच</strong>, या <strong>लाइव जाने या रिकॉर्डिंग शुरू करने के बाद से बीता समय</strong> दिखाता है। इसे इसकी <strong>प्रॉपर्टीज़</strong> से शुरू करें, रोकें और रीसेट करें, या वे दो ग्लोबल हॉटकी सेट करें जो एक साथ <em>हर</em> टाइमर को चलाती हैं (<strong>सेटिंग्स → हॉटकी</strong>)।","manual.fcd4f802968f":"एक <strong>टेक्स्ट</strong> सोर्स <strong>निगरानी में रखी फ़ाइल से पढ़ सकता है</strong> (<strong>प्रॉपर्टीज़ → फ़ाइल से पढ़ें</strong>): पूरी <code>.txt</code> फ़ाइल, एक CSV सेल (कॉलम के नाम या संख्या से), या एक JSON मान (जैसे <code>/teams/0/score</code> पॉइंटर)। बदलाव आधे सेकंड के भीतर दिखते हैं। पीछे किसी सेवा के बिना स्कोरबोर्ड और लोअर थर्ड।","manual.1d106549f0ce":"हॉटकी मैप और मिक्सर कंसोल","manual.5d6ad89f147c":"<strong>हॉटकी मैप</strong> (कमांड पैलेट → &quot;हॉटकी मैप…&quot;) <em>हर</em> बाइंडिंग की सूची दिखाता है — ग्लोबल कार्रवाइयाँ और हर सोर्स का पुश-टू-टॉक और पुश-टू-म्यूट — जिसे खोजा और फ़िल्टर किया जा सकता है, और टकरावों को ईमानदारी से दिखाता है: दो तरह से लिखा गया एक ही शॉर्टकट साझा के रूप में दिखता है, और जिस कुंजी को सिस्टम ने नकार दिया (क्योंकि वह किसी दूसरे ऐप की है) उसके बारे में यह साफ़ बताया जाता है। <strong>चीट शीट निर्यात करें</strong> आपके Downloads फ़ोल्डर में एक Markdown संदर्भ लिखता है।","manual.e32e382b9753":"हर मिक्सर स्ट्रिप में <strong>पैन</strong> (स्टीरियो बैलेंस; बीच में होने का मतलब ठीक शून्य पैन है, और डबल-क्लिक इसे रीसेट करता है), <strong>PFL सोलो</strong> (मॉनिटर में सिर्फ़ सोलो की गई स्ट्रिप सुनाई देती हैं; प्रोग्राम मिक्स कभी नहीं बदलता) और <strong>मोनो</strong> फ़ोल्ड-डाउन होता है। पैन और मोनो स्ट्रिप के &quot;⋯&quot; मेन्यू में हैं; सोलो स्ट्रिप पर ही है।","manual.5dbd70dfc92d":"गहरे डिवाइस विकल्प: डी-इंटरलेसिंग और कैमरा नियंत्रण","manual.f8e60899a881":"वीडियो कैप्चर डिवाइस की <strong>प्रॉपर्टीज़</strong> इंटरलेस्ड फ़ीड के लिए <strong>डी-इंटरलेसिंग</strong> देती हैं, जैसे पुराने कैमरों और कंसोल से जुड़े कैप्चर कार्ड: discard, bob, linear, blend या motion-adaptive, फ़ील्ड क्रम के साथ। यह हर सिस्टम पर एक जैसा चलता है; इसे बदलने पर डिवाइस रीस्टार्ट होता है।","manual.34192e6d30fd":"<strong>कैमरा नियंत्रण</strong> — एक्सपोज़र, व्हाइट बैलेंस, फ़ोकस, ज़ूम, गेन और भी बहुत कुछ — कैमरा चलते समय उन्हीं <strong>प्रॉपर्टीज़</strong> में दिखते हैं। Windows और Linux मानक UVC नियंत्रण इस्तेमाल करते हैं; macOS वही दिखाता है जो सिस्टम बताता है, जो अक्सर कुछ नहीं होता, और पैनल ऐसे स्लाइडर दिखाने के बजाय जो कुछ नहीं करते, यह साफ़ बताता है। हर बदलाव <strong>उस कैमरे की प्रोफ़ाइल</strong> में सहेजा जाता है, और कैमरा दोबारा लगाने या ऐप रीस्टार्ट होने पर फिर से लागू होता है; <strong>प्रोफ़ाइल रीसेट</strong> डिफ़ॉल्ट मान वापस ले आता है।","manual.f77f10d8c967":"स्वचालन और नियंत्रण","manual.726216fb4de1":"नियमों, मैक्रो और हार्डवेयर कंट्रोलर से स्टूडियो को ख़ुद चलने दें — इनमें से हर एक स्टूडियो कमांड की एक तय सूची तक सीमित है, इसलिए कोई भी स्वचालन किसी फ़ाइल का नाम नहीं ले सकता, कोई प्रोग्राम शुरू नहीं कर सकता या इंटरनेट तक नहीं पहुँच सकता।","manual.193521bd4921":"नियम, मैक्रो और वेरिएबल","manual.e8ee7ccab125":"<strong>उपकरण → स्वचालन नियम और मैक्रो…</strong> खोलें और एक नियम जोड़ें। नौ ट्रिगर में से एक चुनें (सीन बदलना, स्ट्रीम शुरू या बंद होना, रिकॉर्डिंग शुरू या बंद होना, किसी सोर्स में त्रुटि, किसी ऑडियो लेवल का एक सीमा पार करना, सिस्टम का निष्क्रिय होना, किसी विंडो का फ़ोकस लेना, दिन का कोई समय, या निगरानी में रखी किसी फ़ाइल का बदलना), शर्तें जोड़ें (किसी वेरिएबल का मान, लाइव, रिकॉर्डिंग), और एक स्टूडियो कार्रवाई चुनें। हर नियम <strong>अक्षम</strong> शुरू होता है: उसे सक्रिय करने के लिए चालू करें।","manual.5deaa7ba718f":"चरणों की एक नामित सूची के रूप में मैक्रो बनाएँ — कोई कार्रवाई चलाएँ, इंतज़ार करें, कोई वेरिएबल सेट करें — दोहराव की संख्या और वैकल्पिक ग्लोबल हॉटकी के साथ। इसे ऐप, किसी हॉटकी, किसी नियम या रिमोट-कंट्रोल API से चलाएँ।","manual.30ee5b1326f2":"किसी मैक्रो में एक स्टूडियो <strong>वेरिएबल</strong> सेट करें और उसे किसी भी टेक्स्ट सोर्स में <code>{{name}}</code> के रूप में इस्तेमाल करें: मैक्रो के मान सेट करते ही टेक्स्ट बदल जाता है।","manual.5eb10fc04538":"कंट्रोलर: MIDI, OSC और टच पैनल","manual.ba0c838f1688":"<strong>उपकरण → MIDI नियंत्रण…</strong> खोलें और किसी कार्रवाई, मैक्रो, सीन बदलने, मिक्सर फ़ेडर या म्यूट के लिए उसे कोई पैड, नॉब या फ़ेडर सिखाएँ — ऐसी लाइटों और मोटर वाले फ़ेडरों के साथ जो स्टूडियो की असली स्थिति का पालन करते हैं। जब तक आप कोई MIDI पोर्ट न चुनें, कोई पोर्ट नहीं खुलता।","manual.cc993cb0d974":"TouchOSC जैसे कंट्रोलर और लाइटिंग डेस्क को <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> और <code>/mixer/vol</code> जैसे पते भेजने देने के लिए <strong>OSC सुनें</strong> चालू करें। यह डिफ़ॉल्ट रूप से बंद है और जब तक आप अपने नेटवर्क की अनुमति न दें, सिर्फ़ इसी कंप्यूटर पर सुनता है। OSC का अपना कोई पासवर्ड नहीं होता।","manual.134e5f4269f9":"QR कोड के ज़रिए किसी भी फ़ोन पर एक नियंत्रण पेज देने के लिए <strong>उपकरण → LAN पैनल और टैली…</strong> खोलें — लाइव टैली वाले सीन बटन, मिक्सर फ़ेडर और कार्रवाई कुंजियाँ। हर अनुरोध के लिए पासवर्ड ज़रूरी है, और जब तक आप अपने नेटवर्क की अनुमति न दें, यह सिर्फ़ इसी कंप्यूटर पर सुनता है। टैली पेज पूरी स्क्रीन पर लाल या हरा दिखाता है; किसी एक सीन पर नज़र रखने के लिए <code>?scene=NAME</code> जोड़ें।","manual.fc4cd96b860d":"हॉटकी कॉर्ड और लेयर","manual.ec4a9a334753":"हॉटकी फ़ील्ड में एक सामान्य शॉर्टकट (Ctrl+Shift+M) या दो चरणों वाला कॉर्ड (Ctrl+K, फिर 3) सेट करें — दूसरी कुंजी सिर्फ़ तभी ली जाती है जब कॉर्ड इंतज़ार कर रहा हो। किसी बाइंडिंग को एक <strong>लेयर</strong> दें ताकि वह सिर्फ़ उस लेयर के सक्रिय रहने पर काम करे; लेयर तब तक बदली रहती हैं जब तक आप उन्हें न बदलें।","manual.70ad05980925":"कैमरे और शो रनडाउन","manual.24b33b058b99":"<strong>उपकरण → PTZ कैमरे…</strong> खोलें, उसके VISCA-over-IP पते से एक कैमरा जोड़ें, पैन, टिल्ट और ज़ूम के नामित प्रीसेट सहेजें, और किसी प्रीसेट को किसी सीन से जोड़ें ताकि उस सीन पर जाने से वह शॉट वापस आ जाए। PTZ आपके नेटवर्क पर ही रहता है, और कोई कैमरा सिर्फ़ इसलिए मौजूद होता है क्योंकि आपने उसका पता टाइप किया: कुछ भी खोजा नहीं जाता।","manual.c9d86b995c5a":"<strong>उपकरण → शो रनडाउन दिखाएँ…</strong> खोलें और चरणों की सूची बनाएँ — एक सीन, वह कितनी देर रहता है, और वैकल्पिक कार्रवाइयाँ — हाथ से या अपने-आप आगे बढ़ते हुए, लाइव &quot;आगे क्या है&quot; और बचे हुए समय के साथ। रनडाउन सामान्य, पूर्ववत किए जा सकने वाले तरीक़े से सीन बदलता है और आपके सीन कलेक्शन को कभी संपादित नहीं करता।","manual.5c94bed2d737":"<strong>नोट:</strong> हर नियम, मैक्रो, MIDI या OSC बाइंडिंग, पैनल बटन और रनडाउन चरण कमांड की उसी तय सूची से होकर जाता है जिससे रिमोट-कंट्रोल API, इसलिए कोई भी कंट्रोलर वह नहीं कर सकता जो ऐप के अपने बटन नहीं कर सकते। हर नेटवर्क लिसनर डिफ़ॉल्ट रूप से बंद है और जब तक आप अपने नेटवर्क की अनुमति न दें, इसी कंप्यूटर तक सीमित रहता है, और पोर्ट खुलने से पहले OSC और पैनल की सेटिंग्स आपको चेतावनी देती हैं कि नेटवर्क ट्रैफ़िक एन्क्रिप्टेड नहीं है।","manual.1f3fd1c7ddc9":"मल्टीस्ट्रीम","manual.dcac0a03a29b":"एक साथ कई प्लेटफ़ॉर्म पर स्ट्रीम करें — सीधे अपने कंप्यूटर से, बीच में किसी रिले सेवा के बिना।","manual.42d9628818da":"<strong>सेटिंग्स → स्ट्रीम</strong> में दो या ज़्यादा स्ट्रीम गंतव्य जोड़ें और हर एक को चालू करें।","manual.4144fe0d9694":"अगर किसी प्लेटफ़ॉर्म को अलग बिटरेट चाहिए, तो उसे उसकी अपनी एनकोडर सेटिंग्स दें।","manual.cb21d6bb96be":"<strong>लाइव जाएँ</strong> क्लिक करें: आप एक साथ हर चालू गंतव्य पर प्रसारण करते हैं। आँकड़ा डॉक हर गंतव्य की सेहत और बिटरेट दिखाता है, और एक गंतव्य के विफल होने से बाक़ी कभी नहीं गिरते।","manual.aba9a5f55973":"चाहें तो साथ ही अलग-अलग ट्रैक वाली एक लोकल कॉपी रिकॉर्ड करें, और स्ट्रीम करते हुए रीप्ले हॉटकी से रीप्ले सहेजें।","manual.af9343c245a7":"<strong>आज मुफ़्त:</strong> हर फ़ीचर — मल्टीस्ट्रीम, SRT और WHIP, हर फ़िल्टर, स्क्रिप्टिंग, रीप्ले, ट्रांज़िशन पैक और रिमोट-कंट्रोल API — आज सबके लिए मुफ़्त है। भविष्य के संस्करण बेचे जा सकते हैं।","manual.c08320c45003":"स्ट्रीमिंग की विश्वसनीयता और समझ","manual.532ab322d03c":"अपने शो का रिहर्सल करें, उसे मापें और समझें। यहाँ की हर चीज़ डिफ़ॉल्ट रूप से बंद या तटस्थ है, और इसमें से कुछ भी ऑनलाइन नहीं जाता।","manual.80390ae1a9d7":"नेटवर्क सिम्युलेटर","manual.7e620ced841e":"<strong>सेटिंग्स → स्ट्रीम</strong> में <strong>नेटवर्क सिम्युलेटर (रिहर्सल)</strong> खोलें और एक <strong>प्रोफ़ाइल</strong> चुनें — <strong>होटल वाई-फ़ाई</strong>, <strong>मोबाइल हॉटस्पॉट</strong>, या अपनी <strong>बैंडविड्थ</strong>, <strong>लेटेंसी</strong>, <strong>जिटर</strong> और तय समय वाले <strong>आउटेज</strong> के साथ <strong>कस्टम</strong>। यह सिर्फ़ रिहर्सल के लोकल आउटपुट पर असर डालता है, ताकि आप दोबारा कनेक्ट होने, मल्टीस्ट्रीम और बिटरेट के विकल्पों का अभ्यास कर सकें; यह किसी असली प्रसारण को कभी धीमा नहीं कर सकता।","manual.b22d8c51e0bd":"रिहर्सल मोड","manual.083772633b86":"पूरी पाइपलाइन — कंपोज़िटर, एनकोडर, मक्सर और दोबारा कनेक्ट होने का असली तर्क — एक लोकल विकल्प में चलाने के लिए बैंगनी <strong>रिहर्सल</strong> बटन दबाएँ, जिसमें <strong>कंप्यूटर से कुछ भी बाहर नहीं जाता</strong>। एक <strong>रिहर्सल</strong> बैज हर लाइव नियंत्रण पर निशान लगाता है, और आपकी स्ट्रीम कुंजियाँ पढ़ी तक नहीं जातीं, इसलिए आप उन्हें पाने से पहले भी रिहर्सल कर सकते हैं। आप रिहर्सल को रिकॉर्ड भी कर सकते हैं।","manual.184d64047c4c":"<strong>सुझाव:</strong> दिन आने से काफ़ी पहले, कमज़ोर और अस्थिर कनेक्शन पर दोबारा कनेक्ट होने का अभ्यास करने के लिए रिहर्सल को नेटवर्क सिम्युलेटर के साथ इस्तेमाल करें।","manual.d2381a584d24":"छूटे फ़्रेमों की टाइमलाइन","manual.a6a72c5410a8":"<strong>सत्र टाइमलाइन</strong> पूरे सत्र को — रेंडर समय, एनकोडर कतार, हर गंतव्य का बिटरेट और छूटे फ़्रेम, दोबारा कनेक्ट होना, सीन बदलना, मार्कर और अलार्म — एक ज़ूम किए जा सकने वाले ग्राफ़ पर दर्ज करती है। जहाँ आँकड़ा डॉक <em>अभी</em> का हाल दिखाता है, वहीं टाइमलाइन बाद में इस सवाल का जवाब देती है कि &quot;43वें मिनट पर क्या हुआ?&quot;","manual.6e9fee1e85fa":"सत्र रिपोर्ट और एनकोडर बेंचमार्क","manual.9dd812cbf648":"सत्र ख़त्म होने पर एक लोकल सारांश पाने के लिए <strong>सेटिंग्स → स्ट्रीम</strong> में <strong>रिकॉर्डिंग के बगल में एक सत्र रिपोर्ट (HTML + Markdown) लिखें</strong> चालू करें: अपटाइम, हर गंतव्य का औसत और अधिकतम बिटरेट, बंद रहने का समय, दोबारा कनेक्ट होना, मार्कर, अलार्म और रिकॉर्डिंग की जगह। यह आपके कंप्यूटर पर ही रहती है और डिफ़ॉल्ट रूप से बंद है।","manual.a9e574b7bd8d":"आपके कंप्यूटर में मौजूद हर एनकोडर, प्रीसेट और रिज़ॉल्यूशन से छोटे एनकोड मापने के लिए <strong>एनकोडर बेंचमार्क चलाएँ…</strong> इस्तेमाल करें — लगभग एक मिनट, पूरी तरह ऑफ़लाइन — फिर परिणाम से <strong>रिकॉर्डिंग सेटिंग्स पर लागू करें</strong> चुनें। विफलताएँ छिपाई नहीं जातीं, सूची में दिखाई जाती हैं, और जब आप लाइव हों या रिकॉर्ड कर रहे हों, तब बेंचमार्क चलने से मना कर देता है।","manual.fae310275ed2":"सिर्फ़ स्ट्रीम में या सिर्फ़ रिकॉर्डिंग में दिखने वाले सोर्स","manual.191da176dd0d":"किसी सोर्स की पंक्ति पर <strong>स्ट्रीम में दिखाएँ</strong> / <strong>स्ट्रीम में छिपाएँ</strong> और <strong>रिकॉर्डिंग में दिखाएँ</strong> / <strong>रिकॉर्डिंग में छिपाएँ</strong> इस्तेमाल करें, ताकि एक ही कैनवस से अलर्ट और चैट लाइव स्ट्रीम में रहें और रिकॉर्डिंग साफ़ रहे। मुख्य आँख वाला बटन अब भी सब कुछ नियंत्रित करता है, और प्रीव्यू, प्रोजेक्टर और मल्टीव्यू हमेशा पूरा प्रोग्राम दिखाते हैं।","manual.46bad2cb618f":"वर्चुअल कैमरा","manual.69ebe5277092":"किसी भी वीडियो-कॉल ऐप में अपने प्रोग्राम को वेबकैम के रूप में इस्तेमाल करें। <strong>1.2.1 में सिर्फ़ Windows पर।</strong>","manual.ba2b6aa952f7":"<strong>नियंत्रण</strong> में <strong>वर्चुअल कैमरा शुरू करें</strong> क्लिक करें। Freally Capture <strong>&quot;Freally Capture Virtual Camera&quot;</strong> नाम का एक सिस्टम कैमरा जोड़ता है।","manual.cb3cb4585f19":"Zoom, Meet, Discord या Teams की वीडियो सेटिंग्स में वह कैमरा चुनें: आपका प्रोग्राम वेबकैम बन जाता है।","manual.83db59f4a370":"इसे हटाने के लिए <strong>वर्चुअल कैमरा रोकें</strong> क्लिक करें।","manual.91c51d55639b":"<strong>हर सिस्टम पर:</strong> <strong>Windows</strong> पर कैमरा बिना एडमिनिस्ट्रेटर अधिकारों के सिर्फ़ आपके यूज़र के लिए रजिस्टर होता है, और रोकने पर हटा दिया जाता है। यह <strong>अभी कोड-साइन नहीं है</strong>, इसलिए Windows इसके बारे में चेतावनी दे सकता है और कोई सख़्त सुरक्षा वाला वीडियो-कॉल ऐप इसे अस्वीकार कर सकता है; लाइव कॉल के अंदर पूरा परीक्षण अभी बाक़ी है। <strong>macOS</strong> और <strong>Linux</strong> के कैमरे अलग कंपोनेंट हैं जो <em>इस रिलीज़ में नहीं हैं</em>। Freally Capture किसी भी सिस्टम पर, बिना पूछे कभी कोई सिस्टम कंपोनेंट इंस्टॉल नहीं करता।","manual.98839b8e6880":"ब्राउज़र सोर्स","manual.3ba821584b20":"एक लाइव वेब पेज — अलर्ट ओवरले, स्कोरबोर्ड, चैट विजेट — सीधे किसी सीन में रखें।","manual.895f07f428cd":"<strong>सोर्स</strong> में <strong>+</strong> क्लिक करें और <strong>ब्राउज़र</strong> चुनें।","manual.868ee19e975e":"एक <strong>http://</strong> या <strong>https://</strong> पता पेस्ट करें और वह आकार और फ़्रेम रेट सेट करें जिस पर उसे रेंडर करना है।","manual.292e94b0a782":"पहली बार Freally Capture <strong>ब्राउज़र रनटाइम</strong> कंपोनेंट इंस्टॉल करने का विकल्प देता है। यह तभी डाउनलोड होता है जब आप इसे माँगते हैं और इसके हैश से इसकी जाँच होती है — यह कभी ऐप के साथ बंडल नहीं होता — और आप इसे <strong>उपकरण → कंपोनेंट</strong> से फिर से हटा सकते हैं।","manual.cd6d7fbd46ee":"<strong>सिर्फ़ http और https लोड होते हैं।</strong> यह नियम हर पेज बदलाव पर लागू होता है, सिर्फ़ आपके टाइप किए पते पर नहीं: अगर कोई पेज <code>file://</code>, <code>javascript:</code> या <code>data:</code> पर जाने की कोशिश करता है — रीडायरेक्ट, स्क्रिप्ट, पॉप-अप या फ़्रेम के ज़रिए — तो वह बदलाव <strong>रद्द</strong> हो जाता है, इसलिए कोई पेज आपकी फ़ाइलें नहीं पढ़ सकता। Windows पर पेज Chromium के सैंडबॉक्स में चलता है। रनटाइम <strong>अभी कोड-साइन नहीं है</strong>। पेज की आवाज़ अभी कैप्चर नहीं होती: यह संस्करण सिर्फ़ तस्वीर दिखाता है।","manual.9c0c8f127dd9":"गेम कैप्चर","manual.2c08692420b8":"ऐसा एक्सक्लूसिव-फ़ुलस्क्रीन गेम कैप्चर करें जिसे सामान्य विंडो कैप्चर नहीं देख सकता। <strong>सिर्फ़ Windows पर।</strong>","manual.9d162e3861e9":"<strong>सोर्स</strong> में <strong>+</strong> क्लिक करें और <strong>गेम कैप्चर</strong> चुनें। <strong>पहले सूचना पढ़ें</strong>: यह जोखिम को सीधे-सादे शब्दों में समझाती है।","manual.4264b41a7732":"जोखिम <em>सिर्फ़ उस एक गेम के लिए</em> स्वीकार करें, फिर सूची से चल रहा गेम चुनें।","manual.ab3e826e90f1":"Freally Capture उस गेम में एक छोटा हुक लोड करता है और गेम के अपने फ़्रेम रेट पर उसके फ़्रेम लेता है।","manual.082fd06e18f9":"<strong>इस्तेमाल करने से पहले इसे पढ़ें।</strong> गेम कैप्चर <strong>गेम में एक DLL लोड करके</strong> काम करता है। एंटी-चीट और एंटीवायरस सॉफ़्टवेयर इसे छेड़छाड़ मान सकते हैं, और इससे कोई खाता <strong>बैन</strong> हो सकता है। कुछ भी कभी अपने-आप लोड नहीं होता: आप <strong>एक बार में एक गेम के लिए</strong> सहमति देते हैं, और वह सहमति कभी किसी दूसरे गेम के लिए इस्तेमाल नहीं हो सकती — और न ही वह कभी किसी साझा सीन कलेक्शन के साथ जाती है। अगर कोई गेम हुक को अस्वीकार कर दे, तो Freally Capture विफल होने के बजाय एक संदेश के साथ सामान्य <strong>विंडो कैप्चर</strong> पर लौट आता है। HDR गेम और Direct3D 12 गेम भी विंडो कैप्चर इस्तेमाल करते हैं। macOS और Linux पर यह सोर्स उपलब्ध नहीं है।","manual.43fae75af922":"रीप्ले बफ़र","manual.40bc664c1c0b":"पिछले पलों को मेमोरी में रखें, ताकि एक हॉटकी से अभी-अभी हुई चीज़ सहेजी जा सके।","manual.7a69241c10c2":"<strong>नियंत्रण</strong> में <strong>रीप्ले बफ़र शुरू करें</strong> क्लिक करें। Freally Capture पिछले कुछ सेकंड एक तय आकार के बफ़र में रखता है।","manual.684aecea2ba0":"<strong>सेटिंग्स</strong> में एक ग्लोबल <strong>रीप्ले सहेजें</strong> हॉटकी सेट करें।","manual.66c44777e965":"पिछले कुछ सेकंड को फ़ाइल में सहेजने के लिए इसे दबाएँ — आपकी स्ट्रीम या मुख्य रिकॉर्डिंग में रुकावट डाले बिना। &quot;रीप्ले सहेजा गया&quot; संदेश इसकी पुष्टि करता है।","manual.4b598d5daf11":"टेलीप्रॉम्प्टर","manual.b7fc474ded62":"कैमरे के सामने वाले व्यक्ति के लिए आसानी से स्क्रॉल होने वाली स्क्रिप्ट — ऐप के एक पैनल पर, मिरर किए जा सकने वाले फ़ुलस्क्रीन प्रोजेक्टर पर, और LAN टच पैनल पर, सब एक साथ।","manual.f1c548f77750":"<strong>उपकरण</strong> से टेलीप्रॉम्प्टर खोलें, अपनी स्क्रिप्ट टाइप या पेस्ट करें, और गति और फ़ॉन्ट सेट करें। गति <strong>अक्षर प्रति सेकंड</strong> में तय करें, या संगीत के साथ ताल मिलाकर गीत पढ़ने के लिए <strong>BPM</strong> (50–250 बीट प्रति मिनट) पर जाएँ; कोई भी बदलाव चल रहे स्क्रॉल की गति तुरंत बदल देता है।","manual.3a86eb91938d":"<strong>विराम चिप:</strong> एक छोटे ठहराव के लिए <code> -- </code> या N सेकंड के ठहराव के लिए <code> --N </code> टाइप करें और वह एक अकेला चिप बन जाता है — कर्सर उसके ऊपर से निकल जाता है, एक Delete या Backspace उसे हटा देता है, और कॉपी-पेस्ट उसे पूरा बनाए रखते हैं।","manual.dc7539148aed":"<strong>काउंटडाउन शुरू करें:</strong> एक वैकल्पिक 3-2-1 शुरुआती गिनती सक्रिय करें, जो ऑपरेटर के प्रीव्यू और प्रोजेक्टर दोनों पर दिखती है, ताकि टेक्स्ट चलने से पहले पढ़ने वाले को एक पल मिल जाए।","manual.f5113c573ac4":"पढ़ने वाले के लिए <strong>प्रोजेक्टर खोलें</strong> (मिरर मोड इसे बीम-स्प्लिटर ग्लास के लिए उलट देता है)। इसे खोलने पर ऑपरेटर विंडो बंद हो जाती है, ताकि उनके पढ़ते समय आप मुख्य विंडो से स्ट्रीम चला सकें; काउंटडाउन सक्रिय होने पर प्रोजेक्टर शुरुआत पर लौटता है, उलटी गिनती करता है और चलने लगता है। स्क्रीन पर दिए नियंत्रणों, किसी हॉटकी, MIDI, OSC या LAN पैनल से चलाएँ, रोकें, बंद करें, पीछे करें, आगे बढ़ाएँ और फिर से शुरू करें — हर नियंत्रण आपस में तालमेल में रहता है।","manual.5298a60b0152":"<strong>ज़ोर से पढ़ें</strong> आपके सिस्टम की अपनी आवाज़ से स्क्रिप्ट सुनाता है: Windows की बिल्ट-इन आवाज़ें, macOS की आवाज़ें, और Linux पर जहाँ इंस्टॉल हो वहाँ <code>spd-say</code> या <code>espeak-ng</code>। कोई स्पीच इंजन बंडल नहीं है।","manual.5de1b5efa245":"<strong>ऑटोकम्प्लीट</strong> टाइप करते समय हल्के धूसर रंग में शब्द और वाक्यांश सुझाता है; स्वीकार करने के लिए Tab दबाएँ। 18 भाषाओं में से हर एक का अपना शब्दकोश आपके कंप्यूटर पर है, जो सिर्फ़ उसी भाषा के लिए लोड होता है जिसमें आप लिख रहे हैं।","manual.7fb5d22a1670":"रिमोट कंट्रोल","manual.b2ba73efdcec":"Stream Deck या Companion जैसे कंट्रोलर से स्टूडियो चलाएँ — डिफ़ॉल्ट रूप से बंद, पासवर्ड से सुरक्षित, आपके अपने कंप्यूटर पर।","manual.6396674fcd28":"<strong>सेटिंग्स → रिमोट कंट्रोल</strong> खोलें, <strong>WebSocket API</strong> चालू करें (डिफ़ॉल्ट रूप से बंद), और एक <strong>पासवर्ड</strong> सेट करें।","manual.56e0d6d295bb":"यह <code>127.0.0.1</code> पर सुनता है — सिर्फ़ इसी कंप्यूटर पर — जब तक आप स्पष्ट रूप से अपने नेटवर्क की अनुमति न दें।","manual.344e52e3eba1":"किसी Companion या Stream Deck क्लाइंट को दिखाए गए पते पर कनेक्ट करें। हार्डवेयर बटनों से सीन बदलें, ट्रांज़िशन चलाएँ, म्यूट और अनम्यूट करें, रिकॉर्डिंग शुरू और बंद करें, और रीप्ले सहेजें।","manual.6664edd9ad4c":"रिमोट मेहमान और शो प्रोडक्शन","manual.75ce17238f9b":"रिमोट-मेहमान सत्र को एक तैयार किए गए शो में बदलें: आठ तक मेहमान, लाइव प्रोग्राम पर ड्रॉइंग, ग्रीन रूम, निजी संकेत, हर मेहमान का कनेक्शन एक नज़र में, और अपने-आप बनने वाला ग्रिड। यहाँ की हर चीज़ डिफ़ॉल्ट रूप से बंद है या किसी कुंजी से नहीं जुड़ी, और जब तक आप किसी को आमंत्रित न करें, कुछ भी कनेक्ट नहीं होता।","manual.02d9e34002c8":"कई मेहमानों वाले सत्र","manual.5a6c2ec7640d":"एक रिमोट-मेहमान सत्र शुरू करें और आमंत्रण लिंक या उसका QR कोड साझा करें: <strong>आप और आठ तक मेहमान</strong>, एक से नौ तक की गैलरी। हर मेहमान एक टाइल है, जिसके अपने म्यूट नियंत्रण, कनेक्शन गुणवत्ता, संकेत चैनल और एक क्लिक में ऑन एयर बैठाने का विकल्प होता है।","manual.34a323a45540":"मेहमान वेब ब्राउज़र में लिंक खोलता है — कुछ भी इंस्टॉल नहीं करना — और अपना कैमरा और माइक्रोफ़ोन भेजने के लिए <strong>जुड़ें</strong> पर टैप करता है। जिस मेहमान के पास Freally Capture है, वह वही आमंत्रण ऐप में भी खोल सकता है। आमंत्रण आपके चुने हुए समय के बाद समाप्त हो जाता है।","manual.4e31042e4a6f":"<strong>नोट:</strong> तस्वीर और आवाज़ सीधे आपके और हर मेहमान के बीच जाती हैं, पीयर-टू-पीयर और रास्ते में एन्क्रिप्टेड; सिर्फ़ कनेक्शन बनाने की प्रक्रिया एक सार्वजनिक सिग्नलिंग सेवा से होकर जाती है। सत्रों का परीक्षण चार मेहमानों के साथ किया गया है; इससे ज़्यादा आपकी बैंडविड्थ और प्रोसेसर पर निर्भर करता है।","manual.33ff43cd0616":"टेलीस्ट्रेटर: लाइव प्रोग्राम पर ड्रॉ करें","manual.d29f651d6eb9":"<strong>टेलीस्ट्रेटर</strong> खोलें और एक टूल चुनें — <strong>पेन</strong>, <strong>हाइलाइटर</strong>, <strong>तीर</strong> या <strong>दीर्घवृत्त</strong> — फिर सीधे प्रोग्राम पर ड्रॉ करें। आपके निशान बनाते ही तस्वीर का हिस्सा बन जाते हैं, इसलिए वे सिर्फ़ आपके प्रीव्यू में नहीं, बल्कि रिकॉर्डिंग और स्ट्रीम में भी दिखते हैं।","manual.9aa7fc0273fb":"निशानों को कुछ देर बाद <strong>फ़ेड</strong> होने दें, या उन्हें साफ़ करने तक <strong>रखें</strong> के लिए <strong>व्हाइटबोर्ड मोड</strong> पर जाएँ। ड्रॉइंग टैबलेट के दबाव का पालन करती है, और <strong>निशान साफ़ करें</strong> को किसी हॉटकी से जोड़ा जा सकता है (डिफ़ॉल्ट रूप से नहीं जुड़ा)।","manual.fc81cd8d37ae":"ग्रीन रूम","manual.c87beb96ec64":"<strong>ग्रीन रूम</strong> चालू करें, और नए मेहमान ऑफ़ एयर इंतज़ार करते हैं, जबकि आप <strong>ग्रीन रूम पूर्वावलोकन</strong> में उनके कैमरा और माइक्रोफ़ोन की जाँच करते हैं। जब वे तैयार हों, <strong>ऑन-एयर बैठाएँ</strong> क्लिक करें। मेहमान को ऐप में या वेब पेज पर &quot;आप ग्रीन रूम में हैं&quot; बैनर दिखता है।","manual.1d47c8224f50":"संकेत और बातचीत","manual.569d461035c1":"सत्र के मौजूदा पीयर-टू-पीयर चैनल से किसी मेहमान को एक निजी <strong>संकेत</strong> भेजें — <strong>30 सेकंड</strong>, <strong>समेटें</strong>, <strong>अगली बारी आपकी</strong> और <strong>ज़ोर से बोलें</strong> जैसे प्रीसेट के साथ। मेहमान इसे एक लाइव काउंटडाउन के साथ देखता है, प्रोग्राम में यह कभी नहीं दिखता।","manual.c66c9d5359bf":"कनेक्शन-गुणवत्ता डैशबोर्ड","manual.4541cc1ee0f5":"हर मेहमान का कनेक्शन लाइव देखें — राउंड-ट्रिप समय, पैकेट लॉस, आपको मिल रहा रिज़ॉल्यूशन और फ़्रेम रेट, और जिटर — हरे, पीले या लाल बैज और एक छोटे इतिहास ग्राफ़ के साथ, ताकि कमज़ोर होता कनेक्शन आपके दर्शकों के ध्यान में आने से पहले दिख जाए।","manual.bf8e764221e5":"अपने-आप बनने वाले मेहमान ग्रिड","manual.ffe3c227cdfc":"ऑन एयर बैठे मेहमानों को एक से नौ तक के साफ़-सुथरे ग्रिड में रखने के लिए <strong>ऑटो-ग्रिड</strong> चालू करें, जो मेहमानों के जुड़ने, जाने या बैठाए जाने पर ख़ुद को फिर से व्यवस्थित कर लेता है, या इसे अभी करने के लिए व्यवस्थित करें बटन दबाएँ। हर सीट अपने मेहमान का नाम <code>{{guestN}}</code> वेरिएबल के रूप में प्रकाशित करती है, इसलिए कोई टाइटल सोर्स अपने-आप अपडेट होने वाली नाम-पट्टी बन जाता है।","manual.e8630fabd4e5":"स्टूडियो प्रबंधन और वर्कफ़्लो","manual.c8c487196725":"पूरे लेआउट को पोर्टेबल और साझा करने लायक़ बनाएँ, अपने सीन के नामित संस्करण रखें, ऐप की थीम बदलें, और अपनी पसंदीदा कार्रवाइयाँ बस एक टैप की दूरी पर रखें — सब आपके कंप्यूटर पर, बिना किसी सर्वर के।","manual.f87995a7cf6c":"सीन पैक और संस्करण","manual.074bb2bf9453":"<strong>सीन कलेक्शन → सीन कलेक्शन प्रबंधित करें…</strong> से वर्कस्पेस डायलॉग खोलें: पैक, तुलना, स्नैपशॉट, बैकअप और डॉक-लेआउट के सभी टूल वहीं हैं।","manual.8dce3a052a05":"मौजूदा कलेक्शन और उसकी फ़ाइलों (इमेज, मीडिया, LUT, मास्क, फ़ॉन्ट) को एक पोर्टेबल <code>.fcappack</code> में बंडल करने के लिए <strong>पैक निर्यात करें…</strong> क्लिक करें। वेब पते और नेटवर्क पाथ बंडल करने के बजाय <em>बाहरी</em> के रूप में सूचीबद्ध होते हैं, और फ़ॉन्ट पर उनके लाइसेंस के लिए निशान लगाया जाता है।","manual.c1bba88df9c5":"<strong>पैक आयात करें…</strong> क्लिक करें और एक <code>.fcappack</code> चुनें: यह एक नए कलेक्शन के रूप में आता है, इस कंप्यूटर पर अपनी फ़ाइलें ढूँढता है, और उसी पर स्विच हो जाता है।","manual.69e7b9f6e8ab":"मौजूदा कलेक्शन की किसी दूसरे कलेक्शन, पैक या स्नैपशॉट से तुलना करने के लिए <strong>तुलना करें और मर्ज करें…</strong> क्लिक करें। जोड़े गए, हटाए गए और बदले गए सीन, सोर्स, ट्रांसफ़ॉर्म, फ़िल्टर और दृश्यता की समीक्षा करें, फिर ठीक-ठीक चुनें कि कौन-से बदलाव लाने हैं। कोई सीन चुनने पर उसके इस्तेमाल किए सोर्स भी साथ आते हैं।","manual.862a75c84629":"<strong>स्नैपशॉट…</strong> क्लिक करें, एक चेकपॉइंट को नाम दें और <strong>स्नैपशॉट सहेजें</strong> चुनें। <strong>पुनर्स्थापित करें</strong> उसे बाद में वापस लाता है — आपका मौजूदा लेआउट पहले एक स्नैपशॉट के रूप में सहेजा जाता है, इसलिए पुनर्स्थापना कभी एकतरफ़ा नहीं होती। 50 तक स्नैपशॉट रखे जाते हैं, और उनकी डिस्क खपत दिखाई जाती है।","manual.8058b1480d14":"<strong>सुझाव:</strong> स्नैपशॉट ऑटोसेव और पूर्ववत के साथ-साथ नामित इतिहास हैं। किसी जोखिम भरे बदलाव से पहले एक ले लें, और आपके पास लौटने के लिए हमेशा एक नाम वाला बिंदु रहेगा।","manual.1d55a62a5fdf":"बैकअप, पुनर्स्थापना और पोर्टेबल मोड","manual.250b89a976de":"वर्कस्पेस डायलॉग में <strong>बैकअप और पुनर्स्थापना…</strong> क्लिक करें, फिर सब कुछ — सेटिंग्स, प्रोफ़ाइल और सीन कलेक्शन — एक <code>.fcapbackup</code> फ़ाइल में सहेजने के लिए <strong>बैकअप निर्यात करें…</strong> क्लिक करें।","manual.560e7e269f11":"नए कंप्यूटर पर <strong>बैकअप से पुनर्स्थापित करें…</strong> क्लिक करें, चुनें कि क्या लाना है (<strong>सेटिंग्स</strong>, <strong>सीन कलेक्शन</strong>, <strong>प्रोफ़ाइल</strong>) और <strong>चयनित पुनर्स्थापित करें</strong> चुनें। पुनर्स्थापित कलेक्शन और प्रोफ़ाइल लोड करने के लिए बाद में Freally Capture रीस्टार्ट करें।","manual.5b26da4b8793":"USB स्टिक से चलाने के लिए, प्रोग्राम के बगल में <code>freally-portable.txt</code> नाम की एक फ़ाइल रखें: तब इसका सारा डेटा आपकी यूज़र प्रोफ़ाइल के बजाय प्रोग्राम के फ़ोल्डर में रहता है। <strong>सेटिंग्स → परिचय</strong> दिखाता है कि पोर्टेबल मोड चालू है या नहीं और डेटा कहाँ है।","manual.a31a49d41d7d":"<strong>नोट:</strong> स्ट्रीम कुंजियाँ और पासवर्ड कभी बैकअप में नहीं लिखे जाते — पुनर्स्थापना के बाद उन्हें फिर से दर्ज करें।","manual.5b446c4ea972":"थीम, लेआउट और त्वरित क्रियाएँ","manual.8eea476bde73":"<strong>सेटिंग्स → दिखावट</strong> खोलें और लाइव <strong>कंट्रास्ट चेतावनियों</strong> के साथ पैलेट संपादित करने के लिए <strong>कस्टम</strong> थीम चुनें, फिर उसे साझा करने के लिए <strong>.fctheme निर्यात करें…</strong> या <strong>.fctheme आयात करें…</strong> इस्तेमाल करें।","manual.7cc0bc3a4e74":"वर्कस्पेस डायलॉग के <strong>डॉक लेआउट</strong> में मौजूदा व्यवस्था को एक नाम से सहेजें, और किसी सहेजे गए लेआउट पर स्विच करने के लिए उस पर क्लिक करें।","manual.c9044c09b979":"किसी भी सेटिंग पर सीधे जाने के लिए <strong>सेटिंग्स</strong> में <strong>सेटिंग्स खोजें…</strong> में टाइप करें; एक निशान दिखाता है कि खोलने के बाद से आपने किन श्रेणियों में बदलाव किया है।","manual.a4640858ad4d":"बटन ग्रिड खोलने के लिए <strong>उपकरण → त्वरित क्रियाएँ…</strong> चुनें। <strong>संपादित करें</strong> क्लिक करें, फिर <strong>बटन जोड़ें</strong>, हर बटन का लेबल और रंग सेट करें, और <strong>पेज</strong> जोड़ें। कोई बटन सीन बदल सकता है, मैक्रो चला सकता है, साउंडबोर्ड पैड बजा सकता है या कोई स्टूडियो कमांड चला सकता है।","manual.74ff6472576d":"<strong>सुझाव:</strong> त्वरित-क्रिया बटन वही स्टूडियो कमांड चलाते हैं जो हॉटकी चलाती हैं, और ग्रिड LAN टच पैनल के साथ साझा होता है: इसे एक बार सेट करें और यह आपके फ़ोन पर भी आ जाता है।","manual.74a883a037bc":"सेटिंग्स","manual.5feaf4600834":"प्रोफ़ाइल, सीन कलेक्शन, हॉटकी और भाषा। आज सब कुछ मुफ़्त है, इसलिए सक्रिय करने को कुछ नहीं है। <strong>सेटिंग्स</strong> श्रेणियों वाली एक ही विंडो है — सामान्य, दिखावट, स्ट्रीमिंग, आउटपुट, रीप्ले, हॉटकी, नेटवर्क, सुगम्यता और परिचय — जो <strong>मेन्यू बार</strong> (फ़ाइल, संपादन, दृश्य, डॉक, प्रोफ़ाइल, सीन कलेक्शन, उपकरण और सहायता) से खुलती है।","manual.9f6a04e85e39":"<strong>लागू करें का मतलब है लागू करना।</strong> सेटिंग्स विंडो एक कॉपी को संपादित करती है: जब तक आप <strong>लागू करें</strong> या <strong>ठीक</strong> क्लिक न करें, कुछ नहीं बदलता, और <strong>रद्द करें</strong> थीम प्रीव्यू समेत ठीक वही वापस ले आता है जो पहले था।","manual.3fc0968ef6f9":"<strong>प्रोफ़ाइल और सीन कलेक्शन:</strong> अलग-अलग सेटअप रखें — मान लीजिए &quot;स्ट्रीमिंग&quot; और &quot;लोकल रिकॉर्डिंग&quot; — और <strong>प्रोफ़ाइल</strong> और <strong>सीन कलेक्शन</strong> मेन्यू से, बिना रीस्टार्ट किए, उनके बीच स्विच करें।","manual.ce6f52861bdb":"<strong>हॉटकी:</strong> हर कार्रवाई को ऐसी सूची से सेट करें जिसमें टकराव हो ही नहीं सकता — किसी एक कार्रवाई के लिए शॉर्टकट चुनें और वह बाक़ी हर कार्रवाई की सूची से ग़ायब हो जाता है, इसलिए दो फ़ीचर कभी एक ही कुंजी साझा नहीं करते। <strong>कोई नहीं</strong> उसे फिर से ख़ाली कर देता है।","manual.be52349f05be":"<strong>सुगम्यता:</strong> मिक्सर के मीटर के रंग चुनें, जिनमें कलर-ब्लाइंड लोगों के लिए सुरक्षित सेट भी है। पूरा ऐप कीबोर्ड से चलता है, और स्क्रीन रीडर लाइव जाने, रिकॉर्डिंग, दोबारा कनेक्ट होने और छूटे फ़्रेमों की घोषणा करते हैं।","manual.a79c94673558":"<strong>भाषा:</strong> 18 भाषाओं में से एक चुनें; ऐप तुरंत बदल जाता है, और अरबी दाएँ से बाएँ पढ़ी जाती है।","manual.59274c49ac87":"समस्या की रिपोर्ट करना","manual.c02ed8aec89d":"कोई समस्या डेवलपर तक पहुँचे या नहीं, यह आप तय करते हैं, और आप ठीक-ठीक देखते हैं कि क्या भेजा जाएगा।","manual.4ed327c34aeb":"जब ऐप कोई ऐसी त्रुटि दिखाता है जो उसने ख़ुद पैदा की है, तो उसके बगल में एक <strong>रिपोर्ट करें</strong> बटन दिखता है।","manual.95da4b53fdcc":"क्रैश के बाद, अगली बार खोलने पर <strong>रिपोर्ट करें</strong> या <strong>खारिज करें</strong> का विकल्प मिलता है।","manual.6207904599f4":"<strong>रिपोर्ट करें</strong> आपके ब्राउज़र में इस साइट पर Freally Capture का रिपोर्ट पेज खोलता है, जिसमें तकनीकी जानकारी पहले से भरी होती है: आप उसे पढ़ सकते हैं, लेकिन बदल नहीं सकते। लिखें कि आप क्या कर रहे थे और, चाहें तो, एक ईमेल पता भी जोड़ें। जब तक आप वहाँ <strong>भेजें</strong> न दबाएँ, कुछ भी नहीं भेजा जाता।","manual.6acd4e789ccd":"बैकग्राउंड में कभी कुछ नहीं भेजा जाता, और <strong>खारिज करें</strong> कुछ भी नहीं भेजता।","manual.69bd78234ffb":"निजता और नेटवर्क","manual.42f9b04c2640":"Freally Capture में न कोई खाता है, न टेलीमेट्री, और न हमारी कोई क्लाउड सेवा है। यहाँ ठीक-ठीक बताया गया है कि क्या ऑनलाइन जाता है, और क्या नहीं।","manual.81fe73d241a8":"<strong>न खाता, न टेलीमेट्री।</strong> ऐप आपसे कभी साइन इन करने को नहीं कहता और आपके सीन, रिकॉर्डिंग या उपयोग का कोई भी डेटा कभी कहीं नहीं भेजता।","manual.3735a28566e9":"<strong>आपकी स्ट्रीम सीधे प्लेटफ़ॉर्म पर जाती है।</strong> यह आपके कंप्यूटर से उन सेवाओं तक जाती है जिन्हें आप सेट करते हैं — बीच में हमारा कोई रिले सर्वर नहीं है।","manual.512b8fa00684":"<strong>आपकी रिकॉर्डिंग आपके कंप्यूटर पर ही रहती हैं,</strong> आपके चुने हुए फ़ोल्डर में। कुछ भी अपलोड नहीं होता।","manual.c299fcfa1fde":"<strong>आपकी स्ट्रीम कुंजियाँ आपके कंप्यूटर पर ही रहती हैं,</strong> छिपी हुई दिखाई जाती हैं और सिर्फ़ उसी सेवा को भेजी जाती हैं जिस पर आप स्ट्रीम करते हैं।","manual.414a08bd0219":"<strong>रिमोट मेहमान पीयर-टू-पीयर जुड़ते हैं।</strong> सिर्फ़ सत्र का कनेक्शन बनाने की प्रक्रिया एक सार्वजनिक सिग्नलिंग सेवा से होकर जाती है, और वह भी सिर्फ़ तब जब आप सत्र शुरू करते हैं।","manual.20c95c4687b3":"<strong>चैट ओवरले सार्वजनिक चैट पढ़ता है,</strong> उस चैनल से जिस पर आप उसे लगाते हैं, ठीक वैसे ही जैसे साइन आउट किया हुआ कोई दर्शक पढ़ता — न खाता, न कुंजी, न साइन-इन।","manual.efe87d55bed1":"<strong>दो कंपोनेंट सिर्फ़ तब डाउनलोड होते हैं जब आपको पहली बार उनकी ज़रूरत पड़ती है:</strong> ffmpeg, प्लेटफ़ॉर्म जिन कोडेक की माँग करते हैं उनके लिए, और ब्राउज़र रनटाइम, ब्राउज़र सोर्स के लिए। हर एक अपने प्रकाशक से आता है और इस्तेमाल से पहले उसकी जाँच होती है।","manual.3601a272b3b0":"<strong>अपडेट जाँच</strong> हर बार ऐप खुलने पर, और जब आप <strong>अपडेट जाँचें…</strong> चुनते हैं, एक छोटी फ़ाइल लाती है। इसके साथ आपके या आपके कंप्यूटर के बारे में कुछ भी नहीं भेजा जाता, और जब तक आप हाँ न कहें, कुछ भी इंस्टॉल नहीं होता।","manual.11abc96d8e21":"<strong>समस्या की रिपोर्ट सिर्फ़ तभी भेजी जाती है जब आप भेजें दबाते हैं</strong> — रिपोर्ट पेज पर, और उसमें क्या है यह पढ़ लेने के बाद (<a href=\"#report\">समस्या की रिपोर्ट करना</a> देखें)।","manual.804fa6536d40":"<strong>कोई AI नहीं।</strong> हर फ़िल्टर — शोर दबाना, क्रोमा की, टोन-मैपिंग — पारंपरिक सिग्नल प्रोसेसिंग है। ऐप में कोई मशीन-लर्निंग मॉडल नहीं है और यह कोई मॉडल डाउनलोड भी नहीं करता।"}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
